insert into public.recipes (id, name, description, meal_type, main, emoji, prep_time_min, difficulty, calories, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg, ingredients, seasonings, instructions, appliances, keywords, dietary_tags, i18n, sort) values
  ('d-turkey-sweet-potato-mash', 'Turkey Steaks with Sweet Potato Mash', 'Pan-fried turkey with sweet potato mash and broccoli', 'dinner', 'turkey', '🦃', 25, 'balanced', 604, 49, 70, 16, 13, 15, 392, '[{"name":"turkey","amount":170,"unit":"g"},{"name":"sweet potato","amount":300,"unit":"g"},{"name":"broccoli","amount":150,"unit":"g"},{"name":"butter","amount":8,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp paprika","salt","black pepper"]'::jsonb, '["Peel the sweet potato, cut it into chunks and boil for 12 minutes, adding the broccoli florets for the last 4, then drain","Lift out the broccoli and mash the sweet potato with the butter and a pinch of salt","Season the turkey with the paprika, salt and pepper and fry in the oil over medium heat for 4 to 5 minutes per side","Serve the turkey with the mash and broccoli"]'::jsonb, '["stovetop"]'::jsonb, '["light","turkey","sweet potato","broccoli","butter","oil","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Пуешки стекове с пюре от сладък картоф","description":"Пуешко на тиган с пюре от сладък картоф и броколи","instructions":["Обелете сладкия картоф, нарежете го на парчета и го варете 12 минути, като през последните 4 добавите розичките броколи, и отцедете","Извадете броколите и намачкайте сладкия картоф с маслото и щипка сол","Овкусете пуешкото с червения пипер, сол и пипер и го изпържете в олиото на среден огън по 4–5 минути от всяка страна","Поднесете пуешкото с пюрето и броколите"],"seasonings":["1/2 ч.л. червен пипер","сол","черен пипер"]},"nl":{"name":"Kalkoenschnitzels met zoete-aardappelpuree","description":"Gebakken kalkoen met puree van zoete aardappel en broccoli","instructions":["Schil de zoete aardappel, snijd hem in stukken en kook hem 12 minuten; kook de broccoliroosjes de laatste 4 minuten mee en giet af","Schep de broccoli eruit en stamp de zoete aardappel fijn met de boter en een snufje zout","Kruid de kalkoen met het paprikapoeder, zout en peper en bak hem in de olie op middelhoog vuur 4 tot 5 minuten per kant","Serveer de kalkoen met de puree en de broccoli"],"seasonings":["1/2 tl paprikapoeder","zout","zwarte peper"]}}'::jsonb, 120),
  ('d-chicken-meatballs-mushroom-sauce', 'Chicken Meatballs in Mushroom Sauce', 'Chicken mince meatballs in a creamy mushroom sauce with rice', 'dinner', 'chicken mince', '🍄', 30, 'balanced', 703, 38, 66, 32, 3, 6, 157, '[{"name":"chicken mince","amount":160,"unit":"g"},{"name":"mushrooms","amount":100,"unit":"g"},{"name":"cream sauce","amount":70,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper","pinch of dried thyme"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Season the chicken mince, roll it into {8} small balls and brown them in the oil for 6 minutes","Add the diced onion and sliced mushrooms with the thyme and cook for 5 minutes","Pour in the cream sauce with a splash of water, simmer for 4 minutes and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","chicken mince","mushrooms","cream sauce","rice","onion","oil","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Пилешки кюфтенца в гъбен сос","description":"Кюфтенца от пилешка кайма в кремообразен гъбен сос с ориз","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Овкусете пилешката кайма, оформете {8} малки топчета и ги запържете в олиото за 6 минути","Добавете нарязания на кубчета лук и нарязаните гъби с мащерката и гответе 5 минути","Изсипете сметановия сос с малко вода, варете на тих огън 4 минути и поднесете върху ориза"],"seasonings":["сол","черен пипер","щипка суха мащерка"]},"nl":{"name":"Kipgehaktballetjes in champignonsaus","description":"Balletjes van kipgehakt in een romige champignonsaus met rijst","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Kruid het kipgehakt, rol er {8} kleine balletjes van en bak ze 6 minuten bruin in de olie","Voeg de blokjes ui en de plakjes champignon met de tijm toe en bak 5 minuten","Giet de roomsaus met een scheutje water erbij, laat 4 minuten zachtjes koken en serveer op de rijst"],"seasonings":["zout","zwarte peper","snufje gedroogde tijm"]}}'::jsonb, 121),
  ('d-meatballs-tomato-mash', 'Meatballs in Tomato Sauce with Mash', 'Mixed mince meatballs braised in tomato sauce, with mashed potatoes', 'dinner', 'mixed mince', '🍅', 35, 'balanced', 735, 36, 71, 35, 10, 13, 219, '[{"name":"mixed mince","amount":150,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"tomato sauce","amount":150,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"butter","amount":8,"unit":"g"},{"name":"milk","amount":30,"unit":"ml"}]'::jsonb, '["1 tsp paprika","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes, drain and mash with the butter and milk","Mix the mixed mince with the finely diced onion, paprika, salt and pepper and roll into {8} balls","Brown them in a dry non-stick pan for 6 minutes, turning","Add the tomato sauce, cover and simmer for 10 minutes, then serve with the mash"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","mixed mince","potatoes","tomato sauce","onion","butter","milk","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Кюфтенца в доматен сос с пюре","description":"Кюфтенца от смесена кайма, задушени в доматен сос, с картофено пюре","instructions":["Сварете картофите, нарязани на парчета, в подсолена вода за 15 минути, отцедете ги и ги намачкайте с маслото и млякото","Смесете смесената кайма със ситно нарязания лук, червения пипер, сол и пипер и оформете {8} топчета","Запържете ги в сух незалепващ тиган за 6 минути, като ги обръщате","Добавете доматения сос, покрийте и варете на тих огън 10 минути, след което поднесете с пюрето"],"seasonings":["1 ч.л. червен пипер","сол","черен пипер"]},"nl":{"name":"Gehaktballetjes in tomatensaus met puree","description":"Balletjes van gemengd gehakt gestoofd in tomatensaus, met aardappelpuree","instructions":["Kook de aardappelen, in stukken gesneden, 15 minuten in water met zout, giet af en stamp ze fijn met de boter en de melk","Meng het gemengde gehakt met de fijngesneden ui, het paprikapoeder, zout en peper en rol er {8} balletjes van","Bak ze 6 minuten rondom bruin in een droge koekenpan met antiaanbaklaag; keer regelmatig","Voeg de tomatensaus toe, dek af en laat 10 minuten zachtjes koken; serveer met de puree"],"seasonings":["1 tl paprikapoeder","zout","zwarte peper"]}}'::jsonb, 122),
  ('d-pork-mince-potato-skillet', 'Pork and Potato Skillet', 'Pork mince fried with potatoes, peppers and onion', 'dinner', 'pork mince', '🥔', 30, 'balanced', 689, 31, 63, 35, 9, 9, 102, '[{"name":"pork mince","amount":140,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"peppers","amount":100,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp paprika","salt","black pepper","handful of fresh parsley"]'::jsonb, '["Cut the potatoes into 1 cm cubes and fry them in the oil over medium heat for 12 minutes until golden","Push them aside and brown the pork mince for 6 minutes","Add the diced peppers and onion with the paprika and cook for 5 minutes","Season and scatter with parsley"]'::jsonb, '["stovetop"]'::jsonb, '["pork mince","potatoes","peppers","onion","oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Свинска кайма с картофи на тиган","description":"Свинска кайма, запържена с картофи, чушки и лук","instructions":["Нарежете картофите на кубчета от 1 см и ги пържете в олиото на среден огън 12 минути до златисто","Избутайте ги настрани и запържете свинската кайма за 6 минути","Добавете нарязаните на кубчета чушки и лук с червения пипер и гответе 5 минути","Овкусете и поръсете с магданоз"],"seasonings":["1 ч.л. червен пипер","сол","черен пипер","шепа пресен магданоз"]},"nl":{"name":"Pannetje met varkensgehakt en aardappel","description":"Varkensgehakt gebakken met aardappelen, paprika en ui","instructions":["Snijd de aardappelen in blokjes van 1 cm en bak ze 12 minuten in de olie op middelhoog vuur goudbruin","Schuif ze opzij en bak het varkensgehakt 6 minuten bruin","Voeg de blokjes paprika en ui met het paprikapoeder toe en bak 5 minuten","Breng op smaak en bestrooi met peterselie"],"seasonings":["1 tl paprikapoeder","zout","zwarte peper","handje verse peterselie"]}}'::jsonb, 123),
  ('d-lentil-shepherds-pie', 'Lentil Shepherd''s Pie', 'Lentils, carrots and peas in gravy under olive oil mash', 'dinner', 'lentils', '🥧', 60, 'weekend', 722, 30, 125, 14, 21, 14, 143, '[{"name":"lentils","amount":80,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"carrots","amount":80,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"tomato paste","amount":15,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["1 stock cube","{350} ml water","1 tsp dried thyme","salt","black pepper"]'::jsonb, '["Soften the diced onion and carrots in a third of the olive oil for 5 minutes, then add the rinsed lentils, tomato paste, thyme, water and stock cube","Simmer for 25 minutes until the lentils are tender and the sauce is thick, then stir in the peas","Meanwhile boil the potatoes, cut into chunks, for 15 minutes, drain and mash with the remaining olive oil and salt","Heat the oven to 200°C, tip the lentils into a baking dish, cover with the mash and bake for 20 minutes"]'::jsonb, '["stovetop","oven"]'::jsonb, '["comfort","lentils","potatoes","carrots","peas","onion","tomato paste","olive oil","stovetop","oven","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Овчарски пай с леща","description":"Леща, моркови и грах в сос под пюре със зехтин","instructions":["Задушете нарязаните на кубчета лук и моркови в една трета от зехтина за 5 минути, след което добавете измитата леща, доматеното пюре, мащерката, водата и кубчето бульон","Варете на тих огън 25 минути, докато лещата омекне и сосът се сгъсти, след което добавете граха","Междувременно сварете картофите, нарязани на парчета, за 15 минути, отцедете ги и ги намачкайте с останалия зехтин и сол","Загрейте фурната на 200°C, изсипете лещата в тава, покрийте с пюрето и печете 20 минути"],"seasonings":["1 кубче бульон","{350} мл вода","1 ч.л. суха мащерка","сол","черен пипер"]},"nl":{"name":"Shepherd''s pie met linzen","description":"Linzen, wortel en doperwten in jus onder puree met olijfolie","instructions":["Bak de blokjes ui en wortel 5 minuten zacht in een derde van de olijfolie en voeg dan de afgespoelde linzen, de tomatenpuree, de tijm, het water en het bouillonblokje toe","Laat 25 minuten zachtjes koken tot de linzen gaar zijn en de saus dik is en roer dan de doperwten erdoor","Kook intussen de aardappelen, in stukken gesneden, 15 minuten, giet af en stamp ze fijn met de rest van de olijfolie en zout","Verwarm de oven voor op 200°C, schep de linzen in een ovenschaal, bedek met de puree en bak 20 minuten"],"seasonings":["1 bouillonblokje","{350} ml water","1 tl gedroogde tijm","zout","zwarte peper"]}}'::jsonb, 124),
  ('d-chickpea-sweet-potato-curry', 'Chickpea and Sweet Potato Curry', 'Mild coconut curry with chickpeas, sweet potato and spinach, with rice', 'dinner', 'chickpeas', '🍠', 35, 'balanced', 815, 22, 126, 27, 19, 17, 558, '[{"name":"chickpeas","amount":150,"unit":"g"},{"name":"sweet potato","amount":200,"unit":"g"},{"name":"coconut milk","amount":80,"unit":"g"},{"name":"spinach","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"rice","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp curry powder","1/2 tsp chili flakes","{200} ml water","salt"]'::jsonb, '["Dice the onion and soften it in the oil for 4 minutes, then add the chopped garlic, curry powder and chili flakes","Add the sweet potato in 2 cm cubes, the coconut milk and the water and simmer for 15 minutes until tender","Meanwhile boil the rice in salted water for 10 to 12 minutes and drain","Add the drained chickpeas and spinach to the curry, cook 3 more minutes, season and serve with the rice"]'::jsonb, '["stovetop"]'::jsonb, '["spicy","comfort","chickpeas","sweet potato","coconut milk","spinach","onion","garlic","rice","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Къри с нахут и сладък картоф","description":"Меко кокосово къри с нахут, сладък картоф и спанак, с ориз","instructions":["Нарежете лука на кубчета и го задушете в олиото за 4 минути, след което добавете накълцания чесън, кърито и люспите чили","Добавете сладкия картоф на кубчета от 2 см, кокосовото мляко и водата и варете на тих огън 15 минути, докато омекне","Междувременно сварете ориза в подсолена вода за 10–12 минути и го отцедете","Добавете отцедения нахут и спанака към кърито, варете още 3 минути, овкусете и поднесете с ориза"],"seasonings":["1 с.л. къри на прах","1/2 ч.л. люспи чили","{200} мл вода","сол"]},"nl":{"name":"Curry met kikkererwten en zoete aardappel","description":"Milde kokoscurry met kikkererwten, zoete aardappel en spinazie, met rijst","instructions":["Snijd de ui in blokjes en bak hem 4 minuten zacht in de olie; voeg dan de gehakte knoflook, het kerriepoeder en de chilivlokken toe","Voeg de zoete aardappel in blokjes van 2 cm, de kokosmelk en het water toe en laat 15 minuten zachtjes koken tot hij gaar is","Kook intussen de rijst 10 tot 12 minuten in water met zout en giet af","Voeg de uitgelekte kikkererwten en de spinazie toe aan de curry, kook nog 3 minuten, breng op smaak en serveer met de rijst"],"seasonings":["1 el kerriepoeder","1/2 tl chilivlokken","{200} ml water","zout"]}}'::jsonb, 125),
  ('d-potato-pepper-egg-hash', 'Potato, Pepper and Egg Hash', 'Crisp potatoes with peppers and onion, topped with three fried eggs', 'dinner', 'eggs', '🍳', 25, 'balanced', 619, 28, 64, 28, 9, 9, 258, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"peppers","amount":100,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp paprika","salt","black pepper"]'::jsonb, '["Cut the potatoes into 1 cm cubes and fry them in two thirds of the oil over medium heat for 12 minutes until golden","Add the diced peppers and onion with the paprika and cook for 5 minutes","Fry the eggs in the remaining oil in a second pan for 2 to 3 minutes","Season the hash and serve it with the eggs on top"]'::jsonb, '["stovetop"]'::jsonb, '["light","eggs","potatoes","peppers","onion","oil","stovetop","dinner"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Хаш с картофи, чушки и яйца","description":"Хрупкави картофи с чушки и лук, с три яйца на очи отгоре","instructions":["Нарежете картофите на кубчета от 1 см и ги пържете в две трети от олиото на среден огън 12 минути до златисто","Добавете нарязаните на кубчета чушки и лук с червения пипер и гответе 5 минути","Изпържете яйцата в останалото олио във втори тиган за 2–3 минути","Овкусете картофите и ги поднесете с яйцата отгоре"],"seasonings":["1 ч.л. червен пипер","сол","черен пипер"]},"nl":{"name":"Hash met aardappel, paprika en ei","description":"Knapperige aardappelen met paprika en ui, met drie gebakken eieren erop","instructions":["Snijd de aardappelen in blokjes van 1 cm en bak ze 12 minuten in twee derde van de olie op middelhoog vuur goudbruin","Voeg de blokjes paprika en ui met het paprikapoeder toe en bak 5 minuten","Bak de eieren 2 tot 3 minuten in de rest van de olie in een tweede pan","Breng de hash op smaak en serveer met de eieren erop"],"seasonings":["1 tl paprikapoeder","zout","zwarte peper"]}}'::jsonb, 126),
  ('d-garlic-butter-shrimp-rice', 'Garlic Butter Shrimp with Rice', 'Shrimp in garlic butter with rice and peas', 'dinner', 'shrimp', '🍤', 20, 'quick', 628, 48, 84, 12, 7, 6, 385, '[{"name":"shrimp","amount":180,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"peas","amount":80,"unit":"g"},{"name":"butter","amount":12,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper","handful of fresh parsley"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, adding the peas for the last 2, then drain","Melt the butter in a pan and gently cook the sliced garlic for 1 minute","Add the shrimp and cook for 2 to 3 minutes until pink","Squeeze in the juice of the lemon, season and serve over the rice and peas with parsley"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","shrimp","rice","peas","butter","garlic","lemon","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Скариди в чесново масло с ориз","description":"Скариди в масло с чесън, с ориз и грах","instructions":["Сварете ориза в подсолена вода за 10–12 минути, като през последните 2 добавите граха, и отцедете","Разтопете маслото в тиган и запържете леко нарязания чесън за 1 минута","Добавете скаридите и гответе 2–3 минути, докато порозовеят","Изстискайте сока от лимона, овкусете и поднесете върху ориза с граха, с магданоз"],"seasonings":["сол","черен пипер","шепа пресен магданоз"]},"nl":{"name":"Garnalen in knoflookboter met rijst","description":"Garnalen in knoflookboter met rijst en doperwten","instructions":["Kook de rijst 10 tot 12 minuten in water met zout, kook de doperwten de laatste 2 minuten mee en giet af","Smelt de boter in een pan en bak de plakjes knoflook 1 minuut zachtjes","Voeg de garnalen toe en bak 2 tot 3 minuten tot ze roze zijn","Knijp het sap van de citroen erboven uit, breng op smaak en serveer op de rijst met doperwten, met peterselie"],"seasonings":["zout","zwarte peper","handje verse peterselie"]}}'::jsonb, 127),
  ('d-tuna-fishcakes-salad', 'Tuna Fishcakes with Salad', 'Crisp tuna and potato cakes with lettuce and tomato', 'dinner', 'tuna', '🐟', 35, 'balanced', 593, 43, 66, 20, 9, 6, 448, '[{"name":"tuna","amount":140,"unit":"g"},{"name":"potatoes","amount":250,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"flour","amount":15,"unit":"g"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"oil","amount":12,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper","handful of fresh parsley"]'::jsonb, '["Boil the potatoes, cut into chunks, for 15 minutes, drain well and mash","Mix the mash with the drained tuna, the egg, parsley, salt and pepper and shape into {4} cakes, then dust them with the flour","Fry in the oil over medium heat for 4 minutes per side until crisp and golden","Serve with the lettuce, sliced tomato and the lemon cut into wedges"]'::jsonb, '["stovetop"]'::jsonb, '["light","tuna","potatoes","eggs","flour","lettuce","tomato","oil","lemon","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Кюфтета от риба тон със салата","description":"Хрупкави кюфтета от риба тон и картофи с маруля и домат","instructions":["Сварете картофите, нарязани на парчета, за 15 минути, отцедете ги добре и ги намачкайте","Смесете пюрето с отцедената риба тон, яйцето, магданоза, сол и пипер, оформете {4} кюфтета и ги овалвайте в брашното","Пържете в олиото на среден огън по 4 минути от всяка страна, докато станат хрупкави и златисти","Поднесете с марулята, нарязания домат и лимона, нарязан на резени"],"seasonings":["сол","черен пипер","шепа пресен магданоз"]},"nl":{"name":"Tonijnkoekjes met salade","description":"Krokante koekjes van tonijn en aardappel met sla en tomaat","instructions":["Kook de aardappelen, in stukken gesneden, 15 minuten, giet goed af en stamp ze fijn","Meng de puree met de uitgelekte tonijn, het ei, de peterselie, zout en peper, vorm er {4} koekjes van en bestuif ze met de bloem","Bak in de olie op middelhoog vuur 4 minuten per kant krokant en goudbruin","Serveer met de sla, de plakjes tomaat en de citroen in partjes"],"seasonings":["zout","zwarte peper","handje verse peterselie"]}}'::jsonb, 128),
  ('d-salmon-sweet-potato-traybake', 'Salmon, Sweet Potato and Broccoli Traybake', 'One-tray roast of salmon, sweet potato and broccoli with lemon', 'dinner', 'salmon', '🐟', 35, 'balanced', 684, 39, 66, 31, 13, 15, 277, '[{"name":"salmon","amount":150,"unit":"g"},{"name":"sweet potato","amount":250,"unit":"g"},{"name":"broccoli","amount":150,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1/2 tsp paprika","salt","black pepper"]'::jsonb, '["Heat the oven to 210°C","Cut the sweet potato into 2 cm cubes, toss on a tray with half the olive oil, the paprika and salt and roast for 15 minutes","Add the broccoli florets tossed in the remaining olive oil and the salmon, seasoned, and roast for 12 more minutes","Squeeze over the juice of the lemon"]'::jsonb, '["oven"]'::jsonb, '["salmon","sweet potato","broccoli","olive oil","lemon","oven","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Сьомга със сладък картоф и броколи в тава","description":"Сьомга, сладък картоф и броколи, изпечени в една тава, с лимон","instructions":["Загрейте фурната на 210°C","Нарежете сладкия картоф на кубчета от 2 см, разбъркайте ги в тава с половината зехтин, червения пипер и сол и ги печете 15 минути","Добавете розичките броколи, разбъркани с останалия зехтин, и овкусената сьомга и печете още 12 минути","Изстискайте отгоре сока от лимона"],"seasonings":["1/2 ч.л. червен пипер","сол","черен пипер"]},"nl":{"name":"Traybake met zalm, zoete aardappel en broccoli","description":"Zalm, zoete aardappel en broccoli van één bakplaat, met citroen","instructions":["Verwarm de oven voor op 210°C","Snijd de zoete aardappel in blokjes van 2 cm, meng ze op een bakplaat met de helft van de olijfolie, het paprikapoeder en zout en rooster ze 15 minuten","Voeg de broccoliroosjes, gemengd met de rest van de olijfolie, en de gekruide zalm toe en rooster nog 12 minuten","Knijp het sap van de citroen erover"],"seasonings":["1/2 tl paprikapoeder","zout","zwarte peper"]}}'::jsonb, 129),
  ('d-steak-garlic-potatoes', 'Steak with Garlic Potatoes and Green Beans', 'Seared beef steak with garlic butter potatoes and green beans', 'dinner', 'beef', '🥩', 30, 'balanced', 632, 49, 64, 21, 10, 6, 192, '[{"name":"beef","amount":180,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"green beans","amount":120,"unit":"g"},{"name":"butter","amount":10,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes, adding the green beans for the last 5, then drain","Toss the potatoes in the butter with the chopped garlic over low heat for 2 minutes","Season the beef generously and sear it in the oil over very high heat for 2 to 3 minutes per side","Rest the steak for 3 minutes and serve with the potatoes and beans"]'::jsonb, '["stovetop"]'::jsonb, '["light","beef","potatoes","green beans","butter","garlic","oil","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Стек с чеснови картофи и зелен фасул","description":"Запечатан телешки стек с картофи в чесново масло и зелен фасул","instructions":["Сварете картофите, нарязани на парчета, в подсолена вода за 15 минути, като през последните 5 добавите зеления фасул, и отцедете","Разбъркайте картофите в маслото с накълцания чесън на слаб огън за 2 минути","Овкусете щедро телешкото и го запечатайте в олиото на много силен огън по 2–3 минути от всяка страна","Оставете стека да почине 3 минути и го поднесете с картофите и фасула"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Biefstuk met knoflookaardappelen en sperziebonen","description":"Kort gebakken biefstuk met aardappelen in knoflookboter en sperziebonen","instructions":["Kook de aardappelen, in stukken gesneden, 15 minuten in water met zout, kook de sperziebonen de laatste 5 minuten mee en giet af","Schep de aardappelen 2 minuten om in de boter met de gehakte knoflook op laag vuur","Kruid het rundvlees royaal en schroei het in de olie op zeer hoog vuur 2 tot 3 minuten per kant dicht","Laat de biefstuk 3 minuten rusten en serveer met de aardappelen en de bonen"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 130),
  ('d-creamy-chicken-broccoli-rice-bake', 'Creamy Chicken and Broccoli Rice Bake', 'Chicken, broccoli and rice baked in a cream sauce under cheese', 'dinner', 'chicken', '🧀', 40, 'balanced', 732, 51, 74, 25, 5, 7, 367, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"rice","amount":75,"unit":"g"},{"name":"broccoli","amount":120,"unit":"g"},{"name":"cream sauce","amount":70,"unit":"g"},{"name":"cheese","amount":25,"unit":"g"},{"name":"onion","amount":30,"unit":"g"}]'::jsonb, '["salt","black pepper","pinch of nutmeg"]'::jsonb, '["Heat the oven to 200°C and boil the rice in salted water for 8 minutes, adding the broccoli florets for the last 2, then drain","Cut the chicken into small pieces and fry it with the diced onion in a non-stick pan for 5 minutes","Mix everything with the cream sauce, nutmeg, salt and pepper in a small baking dish","Scatter over the grated cheese and bake for 15 minutes until golden"]'::jsonb, '["stovetop","oven"]'::jsonb, '["comfort","chicken","rice","broccoli","cream sauce","cheese","onion","stovetop","oven","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Кремообразна запеканка с пилешко, броколи и ориз","description":"Пилешко, броколи и ориз, запечени в сметанов сос под кашкавал","instructions":["Загрейте фурната на 200°C и сварете ориза в подсолена вода за 8 минути, като през последните 2 добавите розичките броколи, и отцедете","Нарежете пилешкото на малки парчета и го запържете с нарязания на кубчета лук в незалепващ тиган за 5 минути","Смесете всичко със сметановия сос, индийското орехче, сол и пипер в малка тава","Поръсете с настъргания кашкавал и печете 15 минути до златисто"],"seasonings":["сол","черен пипер","щипка индийско орехче"]},"nl":{"name":"Romige rijstschotel met kip en broccoli","description":"Kip, broccoli en rijst gebakken in een roomsaus onder kaas","instructions":["Verwarm de oven voor op 200°C en kook de rijst 8 minuten in water met zout; kook de broccoliroosjes de laatste 2 minuten mee en giet af","Snijd de kip in kleine stukjes en bak ze 5 minuten met de blokjes ui in een koekenpan met antiaanbaklaag","Meng alles met de roomsaus, de nootmuskaat, zout en peper in een kleine ovenschaal","Bestrooi met de geraspte kaas en bak 15 minuten goudbruin"],"seasonings":["zout","zwarte peper","snufje nootmuskaat"]}}'::jsonb, 131),
  ('d-crispy-tofu-sweet-potato', 'Crispy Tofu with Sweet Potato and Green Beans', 'Pan-crisped tofu with roasted sweet potato and green beans', 'dinner', 'tofu', '🍠', 35, 'balanced', 617, 37, 64, 28, 15, 14, 170, '[{"name":"tofu","amount":180,"unit":"g"},{"name":"sweet potato","amount":250,"unit":"g"},{"name":"green beans","amount":120,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp smoked paprika","salt","black pepper","squeeze of lemon juice"]'::jsonb, '["Heat the oven to 210°C, cut the sweet potato into wedges, toss with half the oil, the paprika and salt and roast for 25 minutes","Add the green beans to the tray for the last 10 minutes","Pat the tofu dry, cut into slabs, season and fry in the remaining oil for 4 minutes per side until crisp","Serve together with a squeeze of lemon"]'::jsonb, '["stovetop","oven"]'::jsonb, '["light","tofu","sweet potato","green beans","oil","stovetop","oven","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Хрупкаво тофу със сладък картоф и зелен фасул","description":"Хрупкаво тофу на тиган с печен сладък картоф и зелен фасул","instructions":["Загрейте фурната на 210°C, нарежете сладкия картоф на резени, разбъркайте ги с половината олио, червения пипер и сол и ги печете 25 минути","Добавете зеления фасул в тавата през последните 10 минути","Подсушете тофуто, нарежете го на дебели резени, овкусете ги и ги изпържете в останалото олио по 4 минути от всяка страна, докато станат хрупкави","Поднесете заедно с няколко капки лимон"],"seasonings":["1 ч.л. пушен червен пипер","сол","черен пипер","няколко капки лимонов сок"]},"nl":{"name":"Krokante tofu met zoete aardappel en sperziebonen","description":"In de pan krokant gebakken tofu met geroosterde zoete aardappel en sperziebonen","instructions":["Verwarm de oven voor op 210°C, snijd de zoete aardappel in partjes, meng ze met de helft van de olie, het paprikapoeder en zout en rooster ze 25 minuten","Leg de sperziebonen de laatste 10 minuten op de bakplaat","Dep de tofu droog, snijd hem in plakken, kruid ze en bak ze in de rest van de olie 4 minuten per kant krokant","Serveer samen met een kneepje citroen"],"seasonings":["1 tl gerookt paprikapoeder","zout","zwarte peper","kneepje citroensap"]}}'::jsonb, 132),
  ('d-smoky-bean-potato-stew', 'Smoky Bean and Potato Stew', 'Kidney beans, potatoes and carrots in a smoky tomato broth', 'dinner', 'kidney beans', '🥘', 35, 'balanced', 589, 22, 102, 13, 22, 20, 718, '[{"name":"kidney beans","amount":180,"unit":"g"},{"name":"potatoes","amount":250,"unit":"g"},{"name":"carrots","amount":80,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp smoked paprika","1 stock cube","{250} ml water","salt","black pepper"]'::jsonb, '["Dice the onion and soften it in the olive oil for 4 minutes, then stir in the paprika","Add the potatoes and carrots in chunks, the chopped tomatoes, water and stock cube and simmer for 20 minutes until tender","Stir in the drained kidney beans and cook 5 more minutes","Season with salt and pepper"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","light","kidney beans","potatoes","carrots","chopped tomatoes","onion","olive oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Яхния с боб, картофи и пушен пипер","description":"Червен боб, картофи и моркови в доматен бульон с аромат на пушен пипер","instructions":["Нарежете лука на кубчета и го задушете в зехтина за 4 минути, след което добавете червения пипер","Добавете картофите и морковите на парчета, нарязаните домати, водата и кубчето бульон и варете на тих огън 20 минути, докато омекнат","Добавете отцедения червен боб и варете още 5 минути","Овкусете със сол и пипер"],"seasonings":["1 ч.л. пушен червен пипер","1 кубче бульон","{250} мл вода","сол","черен пипер"]},"nl":{"name":"Rokerige stoof van bonen en aardappel","description":"Kidneybonen, aardappelen en wortel in een rokerige tomatenbouillon","instructions":["Snijd de ui in blokjes en bak hem 4 minuten zacht in de olijfolie; roer dan het paprikapoeder erdoor","Voeg de aardappelen en de wortels in stukken, de tomatenblokjes, het water en het bouillonblokje toe en laat 20 minuten zachtjes koken tot alles gaar is","Roer de uitgelekte kidneybonen erdoor en kook nog 5 minuten","Breng op smaak met zout en peper"],"seasonings":["1 tl gerookt paprikapoeder","1 bouillonblokje","{250} ml water","zout","zwarte peper"]}}'::jsonb, 133),
  ('d-turkey-burgers-sweet-potato-wedges', 'Turkey Burgers with Sweet Potato Wedges', 'Lean turkey burger with lettuce and tomato and roasted sweet potato', 'dinner', 'turkey mince', '🍔', 35, 'balanced', 733, 45, 83, 25, 13, 15, 554, '[{"name":"turkey mince","amount":160,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"sweet potato","amount":250,"unit":"g"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp paprika","salt","black pepper","1 tsp mustard"]'::jsonb, '["Heat the oven to 220°C, cut the sweet potato into wedges, toss with most of the oil, the paprika and salt and roast for 25 minutes","Season the turkey mince, shape it into a patty and fry in the remaining oil for 5 minutes per side until cooked through","Toast the bread and spread with mustard","Add the lettuce, burger and sliced tomato and serve with the wedges"]'::jsonb, '["stovetop","oven"]'::jsonb, '["turkey mince","bread","sweet potato","lettuce","tomato","oil","stovetop","oven","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пуешки бургери със сладки картофи на фурна","description":"Постен пуешки бургер с маруля и домат и печен сладък картоф","instructions":["Загрейте фурната на 220°C, нарежете сладкия картоф на резени, разбъркайте ги с по-голямата част от олиото, червения пипер и сол и ги печете 25 минути","Овкусете пуешката кайма, оформете кюфте и го изпържете в останалото олио по 5 минути от всяка страна, докато се сготви","Препечете хляба и го намажете с горчица","Добавете марулята, кюфтето и нарязания домат и поднесете с картофите"],"seasonings":["1/2 ч.л. червен пипер","сол","черен пипер","1 ч.л. горчица"]},"nl":{"name":"Kalkoenburgers met zoete-aardappelpartjes","description":"Magere kalkoenburger met sla en tomaat en geroosterde zoete aardappel","instructions":["Verwarm de oven voor op 220°C, snijd de zoete aardappel in partjes, meng ze met het grootste deel van de olie, het paprikapoeder en zout en rooster ze 25 minuten","Kruid het kalkoengehakt, vorm er een burger van en bak hem in de rest van de olie 5 minuten per kant gaar","Rooster het brood en besmeer het met mosterd","Beleg met de sla, de burger en de plakjes tomaat en serveer met de partjes"],"seasonings":["1/2 tl paprikapoeder","zout","zwarte peper","1 tl mosterd"]}}'::jsonb, 134),
  ('d-fish-pie', 'Fish Pie', 'White fish and peas in a cream sauce under cheesy mash', 'dinner', 'white fish', '🥧', 45, 'weekend', 682, 47, 64, 27, 9, 8, 440, '[{"name":"white fish","amount":170,"unit":"g"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"peas","amount":60,"unit":"g"},{"name":"cream sauce","amount":70,"unit":"g"},{"name":"butter","amount":8,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"}]'::jsonb, '["salt","black pepper","pinch of nutmeg"]'::jsonb, '["Heat the oven to 200°C and boil the potatoes, cut into chunks, for 15 minutes, then drain and mash with the butter","Cut the fish into chunks and mix it in a small baking dish with the peas, cream sauce, nutmeg, salt and pepper","Spread the mash over the top and scatter with the grated cheese","Bake for 25 minutes until golden and bubbling at the edges"]'::jsonb, '["stovetop","oven"]'::jsonb, '["comfort","white fish","potatoes","peas","cream sauce","butter","cheese","stovetop","oven","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Рибен пай","description":"Бяла риба и грах в сметанов сос под пюре с кашкавал","instructions":["Загрейте фурната на 200°C и сварете картофите, нарязани на парчета, за 15 минути, след което ги отцедете и ги намачкайте с маслото","Нарежете рибата на парчета и я смесете в малка тава с граха, сметановия сос, индийското орехче, сол и пипер","Разстелете пюрето отгоре и поръсете с настъргания кашкавал","Печете 25 минути, докато стане златист и започне да къкри по краищата"],"seasonings":["сол","черен пипер","щипка индийско орехче"]},"nl":{"name":"Vispastei","description":"Witvis en doperwten in een roomsaus onder puree met kaas","instructions":["Verwarm de oven voor op 200°C en kook de aardappelen, in stukken gesneden, 15 minuten; giet af en stamp ze fijn met de boter","Snijd de vis in stukken en meng hem in een kleine ovenschaal met de doperwten, de roomsaus, de nootmuskaat, zout en peper","Verdeel de puree erover en bestrooi met de geraspte kaas","Bak 25 minuten tot de schotel goudbruin is en aan de randen bubbelt"],"seasonings":["zout","zwarte peper","snufje nootmuskaat"]}}'::jsonb, 135),
  ('d-honey-mustard-pork-rice', 'Honey Mustard Pork with Rice and Broccoli', 'Pork strips in a honey mustard glaze with rice and broccoli', 'dinner', 'pork', '🍯', 25, 'balanced', 655, 44, 78, 18, 5, 11, 137, '[{"name":"pork","amount":160,"unit":"g"},{"name":"rice","amount":75,"unit":"g"},{"name":"broccoli","amount":150,"unit":"g"},{"name":"honey","amount":10,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["2 tsp mustard","salt","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, adding the broccoli florets for the last 3, then drain","Cut the pork into strips, season and fry in the oil over high heat for 5 minutes until browned","Stir in the honey and mustard with a splash of water and bubble for 1 minute","Serve the pork and its glaze over the rice and broccoli"]'::jsonb, '["stovetop"]'::jsonb, '["pork","rice","broccoli","honey","oil","stovetop","dinner"]'::jsonb, '["gluten-free","dairy-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Свинско с мед и горчица, ориз и броколи","description":"Ивици свинско в глазура от мед и горчица с ориз и броколи","instructions":["Сварете ориза в подсолена вода за 10–12 минути, като през последните 3 добавите розичките броколи, и отцедете","Нарежете свинското на ивици, овкусете ги и ги запържете в олиото на силен огън за 5 минути, докато се зачервят","Добавете меда и горчицата с малко вода и оставете да покъкри 1 минута","Поднесете свинското с глазурата върху ориза и броколите"],"seasonings":["2 ч.л. горчица","сол","черен пипер"]},"nl":{"name":"Varkensvlees met honing en mosterd, rijst en broccoli","description":"Reepjes varkensvlees in een glazuur van honing en mosterd met rijst en broccoli","instructions":["Kook de rijst 10 tot 12 minuten in water met zout, kook de broccoliroosjes de laatste 3 minuten mee en giet af","Snijd het varkensvlees in reepjes, kruid ze en bak ze 5 minuten in de olie op hoog vuur bruin","Roer de honing en de mosterd met een scheutje water erdoor en laat 1 minuut bubbelen","Serveer het vlees met het glazuur op de rijst en de broccoli"],"seasonings":["2 tl mosterd","zout","zwarte peper"]}}'::jsonb, 136),
  ('d-chicken-caesar-salad', 'Chicken Caesar-Style Salad', 'Chicken over crisp lettuce with croutons, parmesan and a lemon yogurt dressing', 'dinner', 'chicken', '🥗', 20, 'quick', 612, 58, 42, 24, 8, 8, 662, '[{"name":"chicken","amount":170,"unit":"g"},{"name":"lettuce","amount":100,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"parmesan","amount":20,"unit":"g"},{"name":"yogurt","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1 tsp mustard","1 small grated garlic clove if you like","salt","black pepper"]'::jsonb, '["Cut the bread into cubes and fry them in half the olive oil for 3 minutes until crisp, then set aside","Season the chicken and fry it in the remaining olive oil for 5 to 6 minutes per side, then slice","Mix the yogurt with the mustard, the juice of the lemon, half the grated parmesan, salt and pepper","Toss the torn lettuce in the dressing and top with the chicken, croutons and remaining parmesan"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","chicken","lettuce","bread","parmesan","yogurt","olive oil","lemon","stovetop","dinner"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Салата тип „Цезар“ с пилешко","description":"Пилешко върху хрупкава маруля с крутони, пармезан и дресинг от лимон и кисело мляко","instructions":["Нарежете хляба на кубчета и ги запържете в половината зехтин за 3 минути, докато станат хрупкави, след което ги оставете настрани","Овкусете пилешкото и го изпържете в останалия зехтин по 5–6 минути от всяка страна, след което го нарежете","Смесете киселото мляко с горчицата, сока от лимона, половината настърган пармезан, сол и пипер","Разбъркайте накъсаната маруля с дресинга и сложете отгоре пилешкото, крутоните и останалия пармезан"],"seasonings":["1 ч.л. горчица","1 малка скилидка настърган чесън по желание","сол","черен пипер"]},"nl":{"name":"Caesarsalade met kip","description":"Kip op knap