  ('d-lentil-chickpea-curry', 'Lentil and Chickpea Curry', 'Thick coconut curry of lentils, chickpeas and spinach with rice', 'dinner', 'lentils', '🍛', 40, 'balanced', 908, 37, 135, 27, 20, 9, 379, '[{"name":"lentils","amount":80,"unit":"g"},{"name":"chickpeas","amount":120,"unit":"g"},{"name":"coconut milk","amount":80,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"spinach","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp curry powder","1/2 tsp chili flakes","{350} ml water","salt"]'::jsonb, '["Dice the onion and soften it in the oil for 4 minutes, then stir in the curry powder and chili flakes","Add the rinsed lentils and the water and simmer for 20 minutes until the lentils are soft","Meanwhile boil the rice in salted water for 10 to 12 minutes and drain","Stir the drained chickpeas, coconut milk and spinach into the lentils, cook 5 more minutes, season with salt and serve with the rice"]'::jsonb, '["stovetop"]'::jsonb, '["spicy","comfort","hearty","lentils","chickpeas","coconut milk","rice","spinach","onion","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Къри с леща и нахут","description":"Гъсто кокосово къри от леща, нахут и спанак с ориз","instructions":["Нарежете лука на кубчета и го задушете в олиото за 4 минути, след което добавете кърито и люспите чили","Добавете измитата леща и водата и варете на тих огън 20 минути, докато лещата омекне","Междувременно сварете ориза в подсолена вода за 10–12 минути и го отцедете","Добавете отцедения нахут, кокосовото мляко и спанака към лещата, варете още 5 минути, овкусете със сол и поднесете с ориза"],"seasonings":["1 с.л. къри на прах","1/2 ч.л. люспи чили","{350} мл вода","сол"]},"nl":{"name":"Curry met linzen en kikkererwten","description":"Dikke kokoscurry van linzen, kikkererwten en spinazie met rijst","instructions":["Snijd de ui in blo