  ('d-loaded-bean-rice-burritos', 'Loaded Bean and Rice Burritos', 'Two burritos packed with spiced kidney beans, rice and corn', 'dinner', 'kidney beans', '🌯', 25, 'balanced', 912, 31, 157, 18, 17, 14, 1451, '[{"name":"kidney beans","amount":200,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"rice","amount":60,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp smoked paprika","salt","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Warm the drained kidney beans in the oil with the cumin, paprika and salt for 3 minutes, crushing about half of them","Stir in the rice, corn and lime juice","Warm the tortillas, divide the filling between them, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","hearty","kidney beans","tortilla","rice","corn","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Богати бурито с боб и ориз","description":"Две бурито, пълни с червен боб с подправки, ориз и царевица","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Затоплете отцедения червен боб в олиото с кимиона, червения пипер и сол за 3 минути, като намачкате около половината","Добавете ориза, царевицата и сока от лайм и разбъркайте","Затоплете тортилите, разпределете плънката върху тях, подгънете краищата и навийте"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. пушен червен пипер","сол","няколко капки сок от лайм"]},"nl":{"name":"Rijk gevulde burrito''s met bonen en rijst","description":"Twee burrito''s vol gekruide kidneybonen, rijst en mais","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Verwarm de uitgelekte kidneybonen 3 minuten in de olie met de komijn, het paprikapoeder en zout en plet ongeveer de helft","Roer de rijst, de mais en het limoensap erdoor","Verwarm de tortilla''s, verdeel de vulling erover, vouw de zijkanten naar binnen en rol op"],"seasonings":["1 tl gemalen komijn","1 tl gerookt paprikapoeder","zout","kneepje limoensap"]}}'::jsonb, 145),
  ('d-spaghetti-carbonara', 'Spaghetti Carbonara', 'Spaghetti with crisp bacon in a silky egg and parmesan sauce', 'dinner', 'eggs', '🥓', 20, 'quick', 899, 45, 84, 41, 4, 4, 907, '[{"name":"bacon","amount":60,"unit":"g"},{"name":"pasta","amount":110,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"parmesan","amount":25,"unit":"g"}]'::jsonb, '["plenty of black pepper"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain, keeping a cup of the water","Fry the chopped bacon in a dry pan for 5 minutes until crisp, then take the pan off the heat","Beat the eggs with the grated parmesan and pepper","Toss the hot pasta in the pan with the bacon, then stir in the egg mixture and a splash of pasta water off the heat until creamy"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","quick","hearty","bacon","pasta","eggs","parmesan","stovetop","dinner"]'::jsonb, '["nut-allergy"]'::jsonb, '{"bg":{"name":"Спагети карбонара","description":"Спагети с хрупкав бекон в копринен сос от яйца и пармезан","instructions":["Сварете пастата в подсолена вряща вода според указанията на опаковката и я отцедете, като запазите една чаша от водата","Запържете нарязания бекон в сух тиган за 5 минути, докато стане хрупкав, и свалете тигана от огъня","Разбийте яйцата с настъргания пармезан и пипер","Разбъркайте горещата паста с бекона в тигана, след което встрани от огъня добавете яйчената смес и малко от водата от пастата и бъркайте, докато стане кремообразно"],"seasonings":["повече черен пипер"]},"nl":{"name":"Spaghetti carbonara","description":"Spaghetti met knapperig spek in een zijdezachte saus van ei en Parmezaanse kaas","instructions":["Kook de pasta in kokend water met zout volgens de verpakking en giet af; bewaar een kopje kookvocht","Bak het gesneden spek 5 minuten in een droge pan knapperig en haal de pan dan van het vuur","Klop de eieren los met de geraspte Parmezaanse kaas en peper","Schep de hete pasta door het spek in de pan en roer dan van het vuur af het eimengsel en een scheutje kookvocht erdoor tot de saus romig is"],"seasonings":["flink wat zwarte peper"]}}'::jsonb, 146),
  ('d-butter-chicken', 'Butter Chicken with Rice', 'Chicken in a mildly spicy, creamy tomato sauce with rice', 'dinner', 'chicken', '🍛', 35, 'balanced', 898, 54, 104, 29, 5, 12, 253, '[{"name":"chicken","amount":180,"unit":"g"},{"name":"tomato sauce","amount":150,"unit":"g"},{"name":"cream sauce","amount":80,"unit":"g"},{"name":"butter","amount":10,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"rice","amount":100,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"}]'::jsonb, '["1 tbsp curry powder","1/2 tsp chili flakes","1 tsp grated ginger","salt"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Soften the diced onion in the butter for 4 minutes, then add the chopped garlic, ginger, curry powder and chili flakes for 1 minute","Add the chicken in chunks and cook for 4 minutes, then the tomato sauce, and simmer for 12 minutes","Stir in the cream sauce, simmer 2 more minutes, season with salt and serve with the rice"]'::jsonb, '["stovetop"]'::jsonb, '["spicy","comfort","hearty","chicken","tomato sauce","cream sauce","butter","onion","rice","garlic","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Бътър чикън с ориз","description":"Пилешко в леко пикантен кремообразен доматен сос с ориз","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Задушете нарязания на кубчета лук в маслото за 4 минути, след което добавете накълцания чесън, джинджифила, кърито и люспите чили за 1 минута","Добавете пилешкото на парчета и гответе 4 минути, след това доматения сос и варете на тих огън 12 минути","Добавете сметановия сос, варете още 2 минути, овкусете със сол и поднесете с ориза"],"seasonings":["1 с.л. къри на прах","1/2 ч.л. люспи чили","1 ч.л. настърган джинджифил","сол"]},"nl":{"name":"Butter chicken met rijst","description":"Kip in een licht pittige, romige tomatensaus met rijst","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Bak de blokjes ui 4 minuten zacht in de boter; voeg dan de gehakte knoflook, de gember, het kerriepoeder en de chilivlokken 1 minuut toe","Voeg de kip in stukken toe en bak 4 minuten, dan de tomatensaus, en laat 12 minuten zachtjes koken","Roer de roomsaus erdoor, laat nog 2 minuten zachtjes koken, breng op smaak met zout en serveer met de rijst"],"seasonings":["1 el kerriepoeder","1/2 tl chilivlokken","1 tl geraspte gember","zout"]}}'::jsonb, 147),
  ('d-loaded-beef-burrito-bowl', 'Loaded Beef Burrito Bowl', 'Rice bowl with spiced beef mince, beans, corn and cheese', 'dinner', 'beef mince', '🥗', 25, 'balanced', 926, 52, 100, 34, 8, 8, 647, '[{"name":"beef mince","amount":160,"unit":"g"},{"name":"rice","amount":90,"unit":"g"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Brown the beef mince in a dry pan over high heat for 6 minutes, then add the cumin, paprika and salt","Stir in the drained kidney beans and corn and heat through","Serve over the rice with the grated cheese, diced tomato and lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","hearty","beef mince","rice","kidney beans","corn","cheese","tomato","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Богата бурито купа с телешка кайма","description":"Купа ориз с телешка кайма с подправки, боб, царевица и кашкавал","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Запържете телешката кайма в сух тиган на силен огън за 6 минути, след което добавете кимиона, червения пипер и сол","Добавете отцедения червен боб и царевицата и затоплете добре","Поднесете върху ориза с настъргания кашкавал, нарязания на кубчета домат и сок от лайм"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","сол","няколко капки сок от лайм"]},"nl":{"name":"Rijk gevulde burritobowl met rundergehakt","description":"Rijstkom met gekruid rundergehakt, bonen, mais en kaas","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Bak het rundergehakt 6 minuten bruin in een droge pan op hoog vuur en voeg dan de komijn, het paprikapoeder en zout toe","Roer de uitgelekte kidneybonen en de mais erdoor en warm goed door","Serveer op de rijst met de geraspte kaas, de tomatenblokjes en limoensap"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","zout","kneepje limoensap"]}}'::jsonb, 148),
  ('d-shrimp-egg-fried-rice', 'Shrimp and Egg Fried Rice', 'Big bowl of fried rice with shrimp, egg and peas', 'dinner', 'shrimp', '🍤', 20, 'quick', 846, 62, 91, 24, 5, 4, 1550, '[{"name":"shrimp","amount":180,"unit":"g"},{"name":"rice","amount":100,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"peas","amount":70,"unit":"g"},{"name":"soy sauce","amount":20,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["1 tsp grated ginger","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it steam dry","Stir-fry the shrimp in the oil over high heat for 2 minutes with the ginger, then add the peas","Push everything aside, crack in the eggs and scramble until just set","Add the rice and soy sauce, stir-fry for 2 minutes and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","hearty","shrimp","rice","eggs","peas","soy sauce","oil","stovetop","dinner"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Пържен ориз със скариди и яйца","description":"Голяма купа пържен ориз със скариди, яйца и грах","instructions":["Сварете ориза в подсолена вода за 10–12 минути, отцедете го и го оставете да изсъхне на парата","Запържете скаридите в олиото на силен огън за 2 минути с джинджифила, като бъркате, и добавете граха","Избутайте всичко настрани, чукнете яйцата и ги бъркайте, докато едва стегнат","Добавете ориза и соевия сос, пържете 2 минути, като бъркате, и овкусете с пипер"],"seasonings":["1 ч.л. настърган джинджифил","черен пипер"]},"nl":{"name":"Gebakken rijst met garnalen en ei","description":"Grote kom gebakken rijst met garnalen, ei en doperwten","instructions":["Kook de rijst 10 tot 12 minuten in water met zout, giet af en laat hem droog stomen","Roerbak de garnalen 2 minuten in de olie op hoog vuur met de gember en voeg dan de doperwten toe","Schuif alles opzij, breek de eieren in de pan en roer ze tot ze net gestold zijn","Voeg de rijst en de sojasaus toe, roerbak 2 minuten en breng op smaak met peper"],"seasonings":["1 tl geraspte gember","zwarte peper"]}}'::jsonb, 149),
  ('d-chicken-shawarma-plate', 'Chicken Shawarma Plate', 'Spiced chicken with rice, chickpeas, garlic yogurt, cucumber and tomato', 'dinner', 'chicken', '🍗', 30, 'balanced', 829, 59, 98, 21, 8, 9, 309, '[{"name":"chicken","amount":180,"unit":"g"},{"name":"rice","amount":90,"unit":"g"},{"name":"chickpeas","amount":80,"unit":"g"},{"name":"greek yogurt","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","1/2 tsp ground coriander","salt"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, adding the drained chickpeas for the last minute, then drain","Slice the chicken thinly and coat it with the cumin, paprika, chili flakes, coriander and salt","Fry in the olive oil over high heat for 6 to 7 minutes until browned at the edges","Serve over the rice and chickpeas with the diced cucumber and tomato and the yogurt"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","hearty","chicken","rice","chickpeas","greek yogurt","cucumber","tomato","olive oil","stovetop","dinner"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Чиния с пилешка шаурма","description":"Пилешко с подправки, ориз, нахут, чесново кисело мляко, краставица и домат","instructions":["Сварете ориза в подсолена вода за 10–12 минути, като през последната минута добавите отцедения нахут, и отцедете","Нарежете пилешкото на тънки ивици и го овкусете с кимиона, червения пипер, люспите чили, кориандъра и сол","Запържете в зехтина на силен огън за 6–7 минути, докато се зачерви по краищата","Поднесете върху ориза с нахута, с нарязаните на кубчета краставица и домат и киселото мляко"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","1/2 ч.л. люспи чили","1/2 ч.л. смлян кориандър","сол"]},"nl":{"name":"Bord kipshoarma","description":"Gekruide kip met rijst, kikkererwten, knoflookyoghurt, komkommer en tomaat","instructions":["Kook de rijst 10 tot 12 minuten in water met zout, kook de uitgelekte kikkererwten de laatste minuut mee en giet af","Snijd de kip in dunne reepjes en wentel ze door de komijn, het paprikapoeder, de chilivlokken, de koriander en zout","Bak 6 tot 7 minuten in de olijfolie op hoog vuur tot de randjes bruin zijn","Serveer op de rijst met kikkererwten, met de blokjes komkommer en tomaat en de yoghurt"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","1/2 tl chilivlokken","1/2 tl gemalen koriander","zout"]}}'::jsonb, 150),
  ('d-tofu-lentil-bolognese', 'Tofu and Lentil Bolognese', 'Pasta with a rich tomato sauce of lentils and crumbled tofu', 'dinner', 'lentils', '🍝', 35, 'balanced', 859, 61, 103, 27, 19, 10, 269, '[{"name":"lentils","amount":70,"unit":"g"},{"name":"tofu","amount":200,"unit":"g"},{"name":"pasta","amount":50,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","pinch of salt","black pepper"]'::jsonb, '["Crush the garlic. Dice the onion and soften it with the garlic in the olive oil in a deep pan over medium heat for 4 minutes","Crumble in the tofu and fry for 5 minutes until it starts to colour","Add the rinsed lentils, the chopped tomatoes, the oregano and {350} ml of water, and simmer for 20 minutes until the lentils are tender and the sauce is thick","Meanwhile cook the pasta in salted boiling water until al dente and drain it","Season the sauce with salt and black pepper and serve it over the pasta"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","hearty","lentils","tofu","pasta","chopped tomatoes","onion","garlic","olive oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Болонезе с тофу и леща","description":"Паста с плътен доматен сос от леща и натрошено тофу","instructions":["Смачкайте чесъна. Нарежете лука на кубчета и го задушете заедно с чесъна в зехтина в дълбок тиган на среден огън за 4 минути","Натрошете тофуто в тигана и го запържете 5 минути, докато започне да се зачервява","Добавете измитата леща, нарязаните домати, ригана и {350} мл вода и варете на тих огън 20 минути, докато лещата омекне и сосът се сгъсти","Междувременно сварете пастата в подсолена вряща вода до готовност ал денте и я отцедете","Овкусете соса със сол и черен пипер и го поднесете върху пастата"],"seasonings":["1 ч.л. сух риган","щипка сол","черен пипер"]},"nl":{"name":"Bolognese van tofu en linzen","description":"Pasta met een volle tomatensaus van linzen en verkruimelde tofu","instructions":["Pers de knoflook. Snijd de ui in blokjes en bak hem met de knoflook 4 minuten zacht in de olijfolie in een diepe pan op middelhoog vuur","Verkruimel de tofu erboven en bak 5 minuten tot hij begint te kleuren","Voeg de afgespoelde linzen, de tomatenblokjes, de oregano en {350} ml water toe en laat 20 minuten zachtjes koken tot de linzen gaar zijn en de saus dik is","Kook intussen de pasta in kokend water met zout beetgaar en giet af","Breng de saus op smaak met zout en zwarte peper en serveer op de pasta"],"seasonings":["1 tl gedroogde oregano","snufje zout","zwarte peper"]}}'::jsonb, 151),
  ('d-chickpea-tofu-spinach-curry', 'Chickpea, Tofu and Spinach Curry', 'Chickpeas and tofu simmered in a tomato and coconut curry with spinach', 'dinner', 'chickpeas', '🍛', 25, 'balanced', 797, 58, 68, 39, 25, 16, 839, '[{"name":"chickpeas","amount":200,"unit":"g"},{"name":"tofu","amount":220,"unit":"g"},{"name":"spinach","amount":100,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"coconut milk","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp curry powder","pinch of salt"]'::jsonb, '["Dice the onion and soften it in the oil in a deep pan over medium heat for 4 minutes, then stir in the curry powder","Cut the tofu into cubes and add it with the drained chickpeas, the chopped tomatoes and the coconut milk","Simmer for 12 minutes until the sauce has thickened","Stir in the spinach until wilted, season with salt and serve"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","hearty","chickpeas","tofu","spinach","chopped tomatoes","onion","coconut milk","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Къри с нахут, тофу и спанак","description":"Нахут и тофу, задушени в къри от домати и кокосово мляко със спанак","instructions":["Нарежете лука на кубчета и го задушете в олиото в дълбок тиган на среден огън за 4 минути, след което добавете кърито","Нарежете тофуто на кубчета и го добавете заедно с отцедения нахут, нарязаните домати и кокосовото мляко","Варете на тих огън 12 минути, докато сосът се сгъсти","Добавете спанака и бъркайте, докато омекне, овкусете със сол и поднесете"],"seasonings":["1 с.л. къри на прах","щипка сол"]},"nl":{"name":"Curry met kikkererwten, tofu en spinazie","description":"Kikkererwten en tofu gestoofd in een curry van tomaat en kokos met spinazie","instructions":["Snijd de ui in blokjes en bak hem 4 minuten zacht in de olie in een diepe pan op middelhoog vuur; roer dan het kerriepoeder erdoor","Snijd de tofu in blokjes en voeg hem toe met de uitgelekte kikkererwten, de tomatenblokjes en de kokosmelk","Laat 12 minuten zachtjes koken tot de saus dikker is","Roer de spinazie erdoor tot hij geslonken is, breng op smaak met zout en serveer"],"seasonings":["1 el kerriepoeder","snufje zout"]}}'::jsonb, 152),
  ('d-bean-tofu-chili', 'Bean and Tofu Chili', 'A thick chili of kidney beans and crumbled tofu with peppers and corn, over a little rice', 'dinner', 'kidney beans', '🌶️', 30, 'balanced', 830, 61, 98, 28, 25, 23, 911, '[{"name":"kidney beans","amount":200,"unit":"g"},{"name":"tofu","amount":220,"unit":"g"},{"name":"chopped tomatoes","amount":250,"unit":"g"},{"name":"peppers","amount":100,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"rice","amount":25,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp cumin","1 tsp smoked paprika","pinch of chili flakes","pinch of salt"]'::jsonb, '["Cook the rice in {60} ml of salted water, covered, for 12 minutes","Dice the onion and the peppers and soften them in the oil in a pot over medium heat for 4 minutes","Crumble in the tofu, add the cumin, smoked paprika and chili flakes and fry for 4 minutes","Add the drained beans, the corn and the chopped tomatoes and simmer for 15 minutes until thick","Season with salt and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","comfort","hearty","kidney beans","tofu","chopped tomatoes","peppers","onion","corn","rice","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Чили с боб и тофу","description":"Гъсто чили от червен боб и натрошено тофу с чушки и царевица, върху малко ориз","instructions":["Сварете ориза в {60} мл подсолена вода под капак за 12 минути","Нарежете лука и чушките на кубчета и ги задушете в олиото в тенджера на среден огън за 4 минути","Натрошете тофуто, добавете кимиона, пушения червен пипер и люспите чили и пържете 4 минути","Добавете отцедения боб, царевицата и нарязаните домати и варете на тих огън 15 минути, докато се сгъсти","Овкусете със сол и поднесете върху ориза"],"seasonings":["1 ч.л. кимион","1 ч.л. пушен червен пипер","щипка люспи чили","щипка сол"]},"nl":{"name":"Chili met bonen en tofu","description":"Een dikke chili van kidneybonen en verkruimelde tofu met paprika en mais, op een beetje rijst","instructions":["Kook de rijst 12 minuten met het deksel op de pan in {60} ml water met zout","Snijd de ui en de paprika in blokjes en bak ze 4 minuten zacht in de olie in een pan op middelhoog vuur","Verkruimel de tofu erboven, voeg de komijn, het gerookte paprikapoeder en de chilivlokken toe en bak 4 minuten","Voeg de uitgelekte bonen, de mais en de tomatenblokjes toe en laat 15 minuten zachtjes koken tot de chili dik is","Breng op smaak met zout en serveer op de rijst"],"seasonings":["1 tl komijn","1 tl gerookt paprikapoeder","snufje chilivlokken","snufje zout"]}}'::jsonb, 153),
  ('d-crispy-tofu-quinoa-greens', 'Crispy Tofu with Quinoa and Greens', 'A big bowl of crisp tofu, quinoa, broccoli and peas with soy sauce', 'dinner', 'tofu', '🥦', 25, 'balanced', 811, 67, 67, 37, 19, 9, 1210, '[{"name":"tofu","amount":280,"unit":"g"},{"name":"quinoa","amount":50,"unit":"g"},{"name":"peas","amount":120,"unit":"g"},{"name":"broccoli","amount":150,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"ml"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Rinse the quinoa and simmer it in {130} ml of water, covered, for 12 minutes, then fluff it with a fork","Pat the tofu very dry and cut it into cubes; cut the broccoli into small florets","Heat the oil in a wide pan over medium-high heat and fry the tofu for 8 minutes, turning, until crisp on all sides","Add the broccoli, the peas and a splash of water, cover and steam for 4 minutes","Pour over the soy sauce, toss and serve on the quinoa"]'::jsonb, '["stovetop"]'::jsonb, '["asian","hearty","tofu","quinoa","peas","broccoli","soy sauce","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Хрупкаво тофу с киноа и зелени зеленчуци","description":"Голяма купа с хрупкаво тофу, киноа, броколи и грах със соев сос","instructions":["Измийте киноата и я варете в {130} мл вода под капак на тих огън 12 минути, след което я разрохкайте с вилица","Подсушете тофуто много добре и го нарежете на кубчета; нарежете броколите на малки розички","Загрейте олиото в широк тиган на умерено силен огън и пържете тофуто 8 минути, като го обръщате, докато стане хрупкаво от всички страни","Добавете броколите, граха и малко вода, покрийте и задушете 4 минути","Полейте със соевия сос, разбъркайте и поднесете върху киноата"],"seasonings":[]},"nl":{"name":"Krokante tofu met quinoa en groene groenten","description":"Een grote kom met krokante tofu, quinoa, broccoli en doperwten met sojasaus","instructions":["Spoel de quinoa af en laat hem 12 minuten zachtjes koken in {130} ml water met het deksel op de pan; maak hem dan los met een vork","Dep de tofu goed droog en snijd hem in blokjes; snijd de broccoli in kleine roosjes","Verhit de olie in een brede pan op middelhoog tot hoog vuur en bak de tofu 8 minuten rondom krokant; keer regelmatig","Voeg de broccoli, de doperwten en een scheutje water toe, dek af en stoom 4 minuten","Giet de sojasaus erover, schep om en serveer op de quinoa"],"seasonings":[]}}'::jsonb, 154),
  ('d-lentil-tofu-dal', 'Lentil and Tofu Dal', 'Lentils cooked soft with tomato, coconut and spices, with tofu and spinach stirred in', 'dinner', 'lentils', '🥣', 30, 'balanced', 764, 60, 72, 33, 19, 8, 292, '[{"name":"lentils","amount":80,"unit":"g"},{"name":"tofu","amount":200,"unit":"g"},{"name":"spinach","amount":100,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"coconut milk","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp curry powder","pinch of turmeric","pinch of salt"]'::jsonb, '["Dice the onion and soften it in the oil in a pot over medium heat for 4 minutes, then stir in the curry powder and turmeric","Add the rinsed lentils, the chopped tomatoes, the coconut milk and {400} ml of water and simmer for 20 minutes, stirring now and then, until the lentils fall apart","Cut the tofu into cubes and add it with the spinach; cook for 3 more minutes","Season with salt and serve"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","hearty","lentils","tofu","spinach","chopped tomatoes","onion","coconut milk","oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Дал с леща и тофу","description":"Леща, сварена до мекота с домати, кокосово мляко и подправки, с добавени тофу и спанак","instructions":["Нарежете лука на кубчета и го задушете в олиото в тенджера на среден огън за 4 минути, след което добавете кърито и куркумата","Добавете измитата леща, нарязаните домати, кокосовото мляко и {400} мл вода и варете на тих огън 20 минути, като бъркате от време на време, докато лещата се разпадне","Нарежете тофуто на кубчета и го добавете заедно със спанака; варете още 3 минути","Овкусете със сол и поднесете"],"seasonings":["1 с.л. къри на прах","щипка куркума","щипка сол"]},"nl":{"name":"Dal met linzen en tofu","description":"Linzen zacht gekookt met tomaat, kokos en specerijen, met tofu en spinazie erdoor","instructions":["Snijd de ui in blokjes en bak hem 4 minuten zacht in de olie in een pan op middelhoog vuur; roer dan het kerriepoeder en de kurkuma erdoor","Voeg de afgespoelde linzen, de tomatenblokjes, de kokosmelk en {400} ml water toe en laat 20 minuten zachtjes koken; roer af en toe, tot de linzen uiteenvallen","Snijd de tofu in blokjes en voeg hem met de spinazie toe; kook nog 3 minuten","Breng op smaak met zout en serveer"],"seasonings":["1 el kerriepoeder","snufje kurkuma","snufje zout"]}}'::jsonb, 155),
  ('d-garlic-tofu-steaks-potatoes', 'Garlic Tofu Steaks with Potatoes and Green Beans', 'Thick slices of tofu seared with garlic, with boiled potatoes and green beans', 'dinner', 'tofu', '🥔', 25, 'balanced', 787, 61, 69, 37, 18, 9, 71, '[{"name":"tofu","amount":300,"unit":"g"},{"name":"potatoes","amount":250,"unit":"g"},{"name":"green beans","amount":200,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp smoked paprika","pinch of salt","black pepper"]'::jsonb, '["Cut the potatoes into chunks and boil them in salted water for 15 minutes, adding the trimmed green beans for the last 5 minutes, then drain","Pat the tofu dry and cut it into thick slices; season with salt, black pepper and the smoked paprika","Heat the olive oil in a pan over medium-high heat and sear the tofu for 4 minutes on each side until deep golden","Add the sliced garlic for the last minute, then serve the tofu with the potatoes and the green beans, spooning the garlic oil over"]'::jsonb, '["stovetop"]'::jsonb, '["hearty","tofu","potatoes","green beans","garlic","olive oil","stovetop","dinner"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Стекове от тофу с чесън, картофи и зелен фасул","description":"Дебели резени тофу, запечатани с чесън, с варени картофи и зелен фасул","instructions":["Нарежете картофите на парчета и ги сварете в подсолена вода за 15 минути, като през последните 5 минути добавите почистения зелен фасул, и отцедете","Подсушете тофуто и го нарежете на дебели резени; овкусете със сол, черен пипер и пушения червен пипер","Загрейте зехтина в тиган на умерено силен огън и запечатайте тофуто по 4 минути от всяка страна до наситено златисто","Добавете нарязания чесън през последната минута и поднесете тофуто с картофите и зеления фасул, полети с чесновия зехтин"],"seasonings":["1 ч.л. пушен червен пипер","щипка сол","черен пипер"]},"nl":{"name":"Tofusteaks met knoflook, aardappelen en sperziebonen","description":"Dikke plakken tofu aangebakken met knoflook, met gekookte aardappelen en sperziebonen","instructions":["Snijd de aardappelen in stukken en kook ze 15 minuten in water met zout; kook de schoongemaakte sperziebonen de laatste 5 minuten mee en giet af","Dep de tofu droog en snijd hem in dikke plakken; kruid met zout, zwarte peper en het gerookte paprikapoeder","Verhit de olijfolie in een pan op middelhoog tot hoog vuur en bak de tofu 4 minuten per kant diep goudbruin","Voeg de laatste minuut de plakjes knoflook toe en serveer de tofu met de aardappelen en de sperziebonen, met de knoflookolie erover geschept"],"seasonings":["1 tl gerookt paprikapoeder","snufje zout","zwarte peper"]}}'::jsonb, 156),
  ('l-chicken-fried-rice', 'Chicken Fried Rice', 'Wok-fried rice with chicken, egg, peas and carrots', 'lunch', 'chicken', '🍚', 20, 'quick', 646, 43, 72, 19, 5, 6, 1049, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"peas","amount":50,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["black pepper","1 tsp grated ginger"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and spread on a plate to steam dry","Cut the chicken into small pieces, dice the onion and carrots, and fry them in the oil over high heat for 5 minutes until the chicken is cooked through","Add the peas and ginger, then push everything aside, crack in the egg and scramble it in the empty half of the pan","Add the rice and soy sauce and stir-fry for 2 minutes until everything is hot and coated"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","chicken","rice","eggs","peas","carrots","onion","soy sauce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пържен ориз с пилешко","description":"Ориз, запържен в уок с пилешко, яйце, грах и моркови","instructions":["Сварете ориза в подсолена вода за 10–12 минути, отцедете го и го разстелете в чиния, за да изсъхне на парата","Нарежете пилешкото на малки парчета, а лука и морковите на кубчета и ги запържете в олиото на силен огън за 5 минути, докато пилешкото се сготви","Добавете граха и джинджифила, избутайте всичко настрани, чукнете яйцето в празната половина на тигана и го разбъркайте","Добавете ориза и соевия сос и пържете 2 минути, като бъркате, докато всичко се затопли и се покрие със соса"],"seasonings":["черен пипер","1 ч.л. настърган джинджифил"]},"nl":{"name":"Gebakken rijst met kip","description":"In de wok gebakken rijst met kip, ei, doperwten en wortel","instructions":["Kook de rijst 10 tot 12 minuten in water met zout, giet af en spreid hem uit op een bord om droog te stomen","Snijd de kip in kleine stukjes en de ui en de wortels in blokjes en bak ze 5 minuten in de olie op hoog vuur tot de kip gaar is","Voeg de doperwten en de gember toe, schuif alles opzij, breek het ei in de lege helft van de pan en roer het tot roerei","Voeg de rijst en de sojasaus toe en roerbak 2 minuten tot alles heet is en bedekt met saus"],"seasonings":["zwarte peper","1 tl geraspte gember"]}}'::jsonb, 157),
  ('l-teriyaki-salmon-rice-bowl', 'Teriyaki Salmon Rice Bowl', 'Glazed salmon over rice with broccoli and carrot', 'lunch', 'salmon', '🍣', 25, 'balanced', 651, 37, 72, 23, 5, 8, 1298, '[{"name":"salmon","amount":130,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"broccoli","amount":100,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"teriyaki","amount":30,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["salt","sesame seeds if you have them"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes; add the broccoli florets to the pot for the last 3 minutes, then drain","Heat the oil in a pan over medium-high heat and cook the salmon for 3 minutes per side","Pour the teriyaki over the salmon and let it bubble for 1 minute, spooning the glaze over the fish","Serve the salmon on the rice with the broccoli and the carrots, coarsely grated, and pour over any glaze left in the pan"]'::jsonb, '["stovetop"]'::jsonb, '["asian","hearty","salmon","rice","broccoli","carrots","teriyaki","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа ориз със сьомга терияки","description":"Глазирана сьомга върху ориз с броколи и морков","instructions":["Сварете ориза в подсолена вода за 10–12 минути; добавете розичките броколи в тенджерата през последните 3 минути и отцедете","Загрейте олиото в тиган на умерено силен огън и гответе сьомгата по 3 минути от всяка страна","Залейте сьомгата със соса терияки и оставете да покъкри 1 минута, като поливате рибата с глазурата","Поднесете сьомгата върху ориза с броколите и едро настърганите моркови и полейте с останалата в тигана глазура"],"seasonings":["сол","сусам, ако имате"]},"nl":{"name":"Rijstkom met teriyakizalm","description":"Geglaceerde zalm op rijst met broccoli en wortel","instructions":["Kook de rijst 10 tot 12 minuten in water met zout; kook de broccoliroosjes de laatste 3 minuten mee en giet dan af","Verhit de olie in een pan op middelhoog tot hoog vuur en bak de zalm 3 minuten per kant","Giet de teriyaki over de zalm en laat 1 minuut bubbelen; schep het glazuur over de vis","Serveer de zalm op de rijst met de broccoli en de grof geraspte wortels en giet het glazuur uit de pan erover"],"seasonings":["zout","sesamzaad als je het hebt"]}}'::jsonb, 158),
  ('l-tofu-broccoli-stir-fry', 'Tofu and Broccoli Stir-Fry', 'Crispy tofu with broccoli and peppers in a garlic soy sauce, on rice', 'lunch', 'tofu', '🥦', 20, 'quick', 587, 36, 68, 22, 9, 6, 892, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"broccoli","amount":120,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp grated ginger","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Pat the tofu dry, cut it into cubes and fry it in the oil over medium-high heat for 6 minutes, turning, until golden on all sides","Add the broccoli in small florets, the sliced peppers and a splash of water and stir-fry for 4 minutes","Stir in the chopped garlic, ginger, pepper and soy sauce, cook 1 more minute and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","tofu","rice","broccoli","peppers","soy sauce","garlic","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Стир-фрай с тофу и броколи","description":"Хрупкаво тофу с броколи и чушки в соев сос с чесън, върху ориз","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Подсушете тофуто, нарежете го на кубчета и го запържете в олиото на умерено силен огън за 6 минути, като го обръщате, докато стане златисто от всички страни","Добавете броколите на малки розички, нарязаните чушки и малко вода и пържете 4 минути, като бъркате","Добавете накълцания чесън, джинджифила, пипера и соевия сос, гответе още 1 минута и поднесете върху ориза"],"seasonings":["1 ч.л. настърган джинджифил","черен пипер"]},"nl":{"name":"Roerbak met tofu en broccoli","description":"Knapperige tofu met broccoli en paprika in een knoflook-sojasaus, op rijst","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Dep de tofu droog, snijd hem in blokjes en bak hem 6 minuten in de olie op middelhoog tot hoog vuur rondom goudbruin; keer regelmatig","Voeg de broccoli in kleine roosjes, de paprikareepjes en een scheutje water toe en roerbak 4 minuten","Roer de gehakte knoflook, de gember, peper en de sojasaus erdoor, bak nog 1 minuut en serveer op de rijst"],"seasonings":["1 tl geraspte gember","zwarte peper"]}}'::jsonb, 159),
  ('l-shrimp-noodle-stir-fry', 'Shrimp Noodle Stir-Fry', 'Quick stir-fried noodles with shrimp, peppers and carrot', 'lunch', 'shrimp', '🍜', 15, 'quick', 511, 39, 63, 12, 6, 8, 1032, '[{"name":"shrimp","amount":130,"unit":"g"},{"name":"noodles","amount":70,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp grated ginger","squeeze of lime juice"]'::jsonb, '["Cook the noodles in boiling water according to the packet, usually 4 minutes, then drain and rinse briefly","Slice the peppers and onion and cut the carrots into thin strips, then stir-fry them in the oil over high heat for 3 minutes","Add the shrimp and ginger and cook for 2 to 3 minutes until the shrimp are pink","Toss in the noodles and soy sauce, heat through for 1 minute and finish with lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","light","shrimp","noodles","peppers","carrots","onion","soy sauce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Пържени нудли със скариди","description":"Бързи пържени нудли със скариди, чушки и морков","instructions":["Сварете нудлите във вряща вода според указанията на опаковката, обикновено 4 минути, след което ги отцедете и ги изплакнете набързо","Нарежете чушките и лука на ивици, а морковите на тънки лентички и ги запържете в олиото на силен огън за 3 минути, като бъркате","Добавете скаридите и джинджифила и гответе 2–3 минути, докато скаридите порозовеят","Добавете нудлите и соевия сос, затоплете 1 минута и овкусете със сок от лайм"],"seasonings":["1 ч.л. настърган джинджифил","няколко капки сок от лайм"]},"nl":{"name":"Roerbaknoedels met garnalen","description":"Snel geroerbakte noedels met garnalen, paprika en wortel","instructions":["Kook de noedels in kokend water volgens de verpakking, meestal 4 minuten; giet af en spoel kort af","Snijd de paprika en de ui in reepjes en de wortels in dunne reepjes en roerbak ze 3 minuten in de olie op hoog vuur","Voeg de garnalen en de gember toe en bak 2 tot 3 minuten tot de garnalen roze zijn","Schep de noedels en de sojasaus erdoor, verwarm 1 minuut en maak af met limoensap"],"seasonings":["1 tl geraspte gember","kneepje limoensap"]}}'::jsonb, 160),
  ('l-peanut-chicken-noodle-salad', 'Peanut Chicken Noodle Salad', 'Cold noodles with chicken, cucumber and a peanut dressing', 'lunch', 'chicken', '🥜', 20, 'quick', 532, 42, 55, 16, 5, 7, 737, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"noodles","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"peanut butter","amount":20,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"g"}]'::jsonb, '["squeeze of lime juice","2 tbsp warm water"]'::jsonb, '["Simmer the chicken in lightly salted water for 12 minutes until cooked through, then shred it with two forks","Cook the noodles according to the packet, drain and rinse under cold water until cool","Whisk the peanut butter with the soy sauce, lime juice and warm water into a pourable dressing","Cut the cucumber and carrots into thin strips and toss everything together with the dressing"]'::jsonb, '["stovetop"]'::jsonb, '["asian","fresh","quick","light","chicken","noodles","cucumber","carrots","peanut butter","soy sauce","stovetop","lunch"]'::jsonb, '["dairy-free","halal","kosher"]'::jsonb, '{"bg":{"name":"Салата с нудли, пилешко и фъстъчен сос","description":"Студени нудли с пилешко, краставица и фъстъчен дресинг","instructions":["Варете пилешкото в леко подсолена вода на тих огън 12 минути, докато се сготви, след което го накъсайте с две вилици","Сварете нудлите според указанията на опаковката, отцедете ги и ги изплакнете със студена вода, докато изстинат","Разбийте фъстъченото масло със соевия сос, сока от лайм и топлата вода до течен дресинг","Нарежете краставицата и морковите на тънки лентички и разбъркайте всичко с дресинга"],"seasonings":["няколко капки сок от лайм","2 с.л. топла вода"]},"nl":{"name":"Noedelsalade met kip en pinda","description":"Koude noedels met kip, komkommer en een pindadressing","instructions":["Laat de kip 12 minuten zachtjes koken in water met een beetje zout tot hij gaar is en trek hem dan met twee vorken uit elkaar","Kook de noedels volgens de verpakking, giet af en spoel onder koud water tot ze koud zijn","Klop de pindakaas met de sojasaus, het limoensap en het warme water tot een schenkbare dressing","Snijd de komkommer en de wortels in dunne reepjes en meng alles met de dressing"],"seasonings":["kneepje limoensap","2 el warm water"]}}'::jsonb, 161),
  ('l-egg-fried-rice', 'Egg Fried Rice with Peas', 'Simple fried rice with scrambled egg, peas and carrot', 'lunch', 'eggs', '🍳', 18, 'quick', 605, 24, 77, 21, 6, 7, 920, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"rice","amount":75,"unit":"g"},{"name":"peas","amount":60,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"soy sauce","amount":12,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it steam dry for a few minutes","Finely dice the onion and carrots and fry them in the oil over high heat for 3 minutes, then add the peas","Push the vegetables aside, crack in the eggs and scramble them until just set","Add the rice and soy sauce, stir-fry for 2 minutes and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","eggs","rice","peas","carrots","onion","soy sauce","oil","stovetop","lunch"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пържен ориз с яйца и грах","description":"Семпъл пържен ориз с бъркани яйца, грах и морков","instructions":["Сварете ориза в подсолена вода за 10–12 минути, отцедете го и го оставете няколко минути да изсъхне на парата","Нарежете лука и морковите на ситни кубчета и ги запържете в олиото на силен огън за 3 минути, след което добавете граха","Избутайте зеленчуците настрани, чукнете яйцата и ги бъркайте, докато едва стегнат","Добавете ориза и соевия сос, пържете 2 минути, като бъркате, и овкусете с пипер"],"seasonings":["черен пипер"]},"nl":{"name":"Gebakken rijst met ei en doperwten","description":"Eenvoudige gebakken rijst met roerei, doperwten en wortel","instructions":["Kook de rijst 10 tot 12 minuten in water met zout, giet af en laat hem een paar minuten droog stomen","Snijd de ui en de wortels in kleine blokjes en bak ze 3 minuten in de olie op hoog vuur; voeg dan de doperwten toe","Schuif de groenten opzij, breek de eieren in de pan en roer ze tot ze net gestold zijn","Voeg de rijst en de sojasaus toe, roerbak 2 minuten en breng op smaak met peper"],"seasonings":["zwarte peper"]}}'::jsonb, 162),
  ('l-spicy-beef-lettuce-cups', 'Spicy Beef Lettuce Cups', 'Chili-garlic beef mince with rice, served in crisp lettuce leaves', 'lunch', 'beef mince', '🥬', 20, 'quick', 559, 31, 51, 25, 4, 3, 790, '[{"name":"beef mince","amount":130,"unit":"g"},{"name":"rice","amount":50,"unit":"g"},{"name":"lettuce","amount":80,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"soy sauce","amount":12,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","1 tsp grated ginger","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Brown the beef mince in the oil over high heat for 5 minutes, breaking it up","Add the chopped garlic, ginger, chili flakes and soy sauce and cook for 2 minutes","Separate the lettuce into cups, fill them with rice, beef and the grated carrots and finish with lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","fresh","quick","beef mince","rice","lettuce","carrots","soy sauce","garlic","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пикантни лодки от маруля с телешка кайма","description":"Телешка кайма с чили и чесън и ориз, поднесени в хрупкави листа маруля","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Запържете телешката кайма в олиото на силен огън за 5 минути, като я разбивате на трохи","Добавете накълцания чесън, джинджифила, люспите чили и соевия сос и гответе 2 минути","Отделете листата на марулята като купички, напълнете ги с ориз, кайма и настърганите моркови и овкусете със сок от лайм"],"seasonings":["1/2 ч.л. люспи чили","1 ч.л. настърган джинджифил","няколко капки сок от лайм"]},"nl":{"name":"Pittige slabakjes met rundergehakt","description":"Rundergehakt met chili en knoflook en rijst, geserveerd in knapperige slabladeren","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Bak het rundergehakt 5 minuten bruin in de olie op hoog vuur en maak het los","Voeg de gehakte knoflook, de gember, de chilivlokken en de sojasaus toe en bak 2 minuten","Maak de slabladeren los tot bakjes, vul ze met rijst, gehakt en de geraspte wortels en maak af met limoensap"],"seasonings":["1/2 tl chilivlokken","1 tl geraspte gember","kneepje limoensap"]}}'::jsonb, 163),
  ('l-coconut-chickpea-curry', 'Spicy Coconut Chickpea Curry', 'Chickpeas and spinach simmered in a spiced coconut tomato sauce', 'lunch', 'chickpeas', '🍛', 20, 'quick', 524, 17, 52, 31, 15, 12, 621, '[{"name":"chickpeas","amount":150,"unit":"g"},{"name":"coconut milk","amount":100,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"spinach","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tbsp curry powder","1/2 tsp chili flakes","salt"]'::jsonb, '["Dice the onion and soften it in the oil over medium heat for 4 minutes, then add the chopped garlic, curry powder and chili flakes for 1 minute","Add the chopped tomatoes, coconut milk and drained chickpeas and simmer for 10 minutes","Stir in the spinach until it wilts and season with salt"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","comfort","quick","light","chickpeas","coconut milk","chopped tomatoes","spinach","onion","garlic","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пикантно къри с нахут и кокосово мляко","description":"Нахут и спанак, задушени в ароматен сос от кокосово мляко и домати","instructions":["Нарежете лука на кубчета и го задушете в олиото на среден огън за 4 минути, след което добавете накълцания чесън, кърито и люспите чили за 1 минута","Добавете нарязаните домати, кокосовото мляко и отцедения нахут и варете на тих огън 10 минути","Добавете спанака, бъркайте, докато омекне, и овкусете със сол"],"seasonings":["1 с.л. къри на прах","1/2 ч.л. люспи чили","сол"]},"nl":{"name":"Pittige kokoscurry met kikkererwten","description":"Kikkererwten en spinazie gestoofd in een gekruide saus van kokos en tomaat","instructions":["Snijd de ui in blokjes en bak hem 4 minuten zacht in de olie op middelhoog vuur; voeg dan de gehakte knoflook, het kerriepoeder en de chilivlokken 1 minuut toe","Voeg de tomatenblokjes, de kokosmelk en de uitgelekte kikkererwten toe en laat 10 minuten zachtjes koken","Roer de spinazie erdoor tot hij slinkt en breng op smaak met zout"],"seasonings":["1 el kerriepoeder","1/2 tl chilivlokken","zout"]}}'::jsonb, 164),
  ('l-teriyaki-chicken-rice-bowl', 'Teriyaki Chicken Rice Bowl', 'Sticky teriyaki chicken with rice, broccoli and carrot', 'lunch', 'chicken', '🍗', 20, 'quick', 541, 40, 73, 9, 5, 9, 1471, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"broccoli","amount":100,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"teriyaki","amount":35,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["sesame seeds if you have them"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, adding the broccoli florets and sliced carrots for the last 3 minutes, then drain","Cut the chicken into bite-sized pieces and fry in the oil over medium-high heat for 6 minutes until golden and cooked through","Add the teriyaki and let it bubble for 1 minute until sticky","Serve the chicken and its sauce over the rice and vegetables"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","light","chicken","rice","broccoli","carrots","teriyaki","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа ориз с пилешко терияки","description":"Лепкаво пилешко терияки с ориз, броколи и морков","instructions":["Сварете ориза в подсолена вода за 10–12 минути, като през последните 3 минути добавите розичките броколи и нарязаните моркови, и отцедете","Нарежете пилешкото на хапки и го запържете в олиото на умерено силен огън за 6 минути, докато стане златисто и се сготви","Добавете соса терияки и оставете да покъкри 1 минута, докато стане лепкав","Поднесете пилешкото със соса върху ориза и зеленчуците"],"seasonings":["сусам, ако имате"]},"nl":{"name":"Rijstkom met teriyakikip","description":"Kleverige teriyakikip met rijst, broccoli en wortel","instructions":["Kook de rijst 10 tot 12 minuten in water met zout, kook de broccoliroosjes en de plakjes wortel de laatste 3 minuten mee en giet af","Snijd de kip in hapklare stukjes en bak ze 6 minuten in de olie op middelhoog tot hoog vuur goudbruin en gaar","Voeg de teriyaki toe en laat 1 minuut bubbelen tot de saus kleverig is","Serveer de kip met de saus op de rijst en de groenten"],"seasonings":["sesamzaad als je het hebt"]}}'::jsonb, 165),
  ('l-ginger-turkey-noodle-soup', 'Ginger Turkey Noodle Soup', 'Light broth with turkey, noodles, mushrooms and spinach', 'lunch', 'turkey', '🍲', 20, 'quick', 423, 38, 47, 10, 5, 5, 836, '[{"name":"turkey","amount":110,"unit":"g"},{"name":"noodles","amount":50,"unit":"g"},{"name":"mushrooms","amount":60,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"soy sauce","amount":12,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 stock cube","{500} ml water","1 tbsp grated ginger"]'::jsonb, '["Slice the turkey thinly and brown it in the oil in a pot for 3 minutes with the chopped garlic and ginger","Add the water, stock cube, sliced carrots and mushrooms and simmer for 6 minutes","Add the noodles and cook for 4 minutes until soft","Stir in the spinach and soy sauce and serve as soon as the spinach wilts"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","light","turkey","noodles","mushrooms","carrots","spinach","soy sauce","garlic","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Супа с нудли, пуешко и джинджифил","description":"Лек бульон с пуешко, нудли, гъби и спанак","instructions":["Нарежете пуешкото на тънки ивици и го запържете в олиото в тенджера за 3 минути с накълцания чесън и джинджифила","Добавете водата, кубчето бульон, нарязаните моркови и гъбите и варете на тих огън 6 минути","Добавете нудлите и варете 4 минути, докато омекнат","Добавете спанака и соевия сос и поднесете веднага щом спанакът омекне"],"seasonings":["1 кубче бульон","{500} мл вода","1 с.л. настърган джинджифил"]},"nl":{"name":"Noedelsoep met kalkoen en gember","description":"Lichte bouillon met kalkoen, noedels, champignons en spinazie","instructions":["Snijd de kalkoen in dunne plakjes en bak hem 3 minuten bruin in de olie in een pan, met de gehakte knoflook en de gember","Voeg het water, het bouillonblokje, de plakjes wortel en de champignons toe en laat 6 minuten zachtjes koken","Voeg de noedels toe en kook 4 minuten tot ze zacht zijn","Roer de spinazie en de sojasaus erdoor en serveer zodra de spinazie geslonken is"],"seasonings":["1 bouillonblokje","{500} ml water","1 el geraspte gember"]}}'::jsonb, 166),
  ('l-spicy-tofu-fried-rice', 'Spicy Tofu Fried Rice', 'Fried rice with golden tofu, peas, peppers and chili', 'lunch', 'tofu', '🌶️', 20, 'quick', 611, 32, 75, 22, 9, 7, 936, '[{"name":"tofu","amount":130,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"peppers","amount":50,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","1 tsp grated ginger"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it steam dry","Cut the tofu into small cubes and fry in the oil over high heat for 5 minutes until golden","Add the diced carrots and peppers, the peas, ginger and chili flakes and stir-fry for 3 minutes","Add the rice and soy sauce and fry for 2 more minutes"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","quick","tofu","rice","peas","carrots","peppers","soy sauce","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пикантен пържен ориз с тофу","description":"Пържен ориз със златисто тофу, грах, чушки и чили","instructions":["Сварете ориза в подсолена вода за 10–12 минути, отцедете го и го оставете да изсъхне на парата","Нарежете тофуто на малки кубчета и го запържете в олиото на силен огън за 5 минути до златисто","Добавете нарязаните на кубчета моркови и чушки, граха, джинджифила и люспите чили и пържете 3 минути, като бъркате","Добавете ориза и соевия сос и пържете още 2 минути"],"seasonings":["1/2 ч.л. люспи чили","1 ч.л. настърган джинджифил"]},"nl":{"name":"Pittige gebakken rijst met tofu","description":"Gebakken rijst met goudbruine tofu, doperwten, paprika en chili","instructions":["Kook de rijst 10 tot 12 minuten in water met zout, giet af en laat hem droog stomen","Snijd de tofu in kleine blokjes en bak ze 5 minuten in de olie op hoog vuur goudbruin","Voeg de blokjes wortel en paprika, de doperwten, de gember en de chilivlokken toe en roerbak 3 minuten","Voeg de rijst en de sojasaus toe en bak nog 2 minuten"],"seasonings":["1/2 tl chilivlokken","1 tl geraspte gember"]}}'::jsonb, 167),
  ('l-spicy-tuna-rice-bowl', 'Spicy Tuna Rice Bowl', 'Rice bowl with tuna, avocado, cucumber and a spicy soy dressing', 'lunch', 'tuna', '🐟', 15, 'quick', 599, 29, 75, 22, 12, 4, 839, '[{"name":"tuna","amount":100,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"carrots","amount":40,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"g"}]'::jsonb, '["1 tsp sriracha or other chili sauce","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it cool slightly","Mix the drained tuna with the soy sauce, chili sauce and lime juice","Dice the avocado and cucumber and grate the carrots","Fill a bowl with the rice and arrange the tuna, avocado, cucumber and carrots on top"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","fresh","quick","tuna","rice","avocado","cucumber","carrots","soy sauce","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пикантна купа ориз с риба тон","description":"Купа ориз с риба тон, авокадо, краставица и пикантен соев дресинг","instructions":["Сварете ориза в подсолена вода за 10–12 минути, отцедете го и го оставете леко да изстине","Смесете отцедената риба тон със соевия сос, лютия сос и сока от лайм","Нарежете авокадото и краставицата на кубчета и настържете морковите","Напълнете купа с ориза и наредете отгоре рибата тон, авокадото, краставицата и морковите"],"seasonings":["1 ч.л. шрирача или друг лют сос","няколко капки сок от лайм"]},"nl":{"name":"Pittige rijstkom met tonijn","description":"Rijstkom met tonijn, avocado, komkommer en een pittige sojadressing","instructions":["Kook de rijst 10 tot 12 minuten in water met zout, giet af en laat hem iets afkoelen","Meng de uitgelekte tonijn met de sojasaus, de chilisaus en het limoensap","Snijd de avocado en de komkommer in blokjes en rasp de wortels","Vul een kom met de rijst en leg de t