  ('l-chicken-fajita-wraps', 'Chicken Fajita Wraps', 'Spiced chicken, peppers and onion in warm tortillas', 'lunch', 'chicken', '🌯', 20, 'quick', 640, 41, 70, 21, 7, 11, 948, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"peppers","amount":100,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Slice the chicken, peppers and onion into strips and toss the chicken with the cumin, paprika and salt","Fry the chicken in the oil over high heat for 5 minutes until browned and cooked through","Add the peppers and onion and cook for 4 minutes until soft with charred edges","Warm the tortillas in a dry pan, fill them and finish with lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","chicken","tortilla","peppers","onion","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Врапове с пилешки фахитас","description":"Пилешко с подправки, чушки и лук в топли тортили","instructions":["Нарежете пилешкото, чушките и лука на ивици и овкусете пилешкото с кимиона, червения пипер и сол","Запържете пилешкото в олиото на силен огън за 5 минути, докато се зачерви и се сготви","Добавете чушките и лука и гответе 4 минути, докато омекнат и леко прегорят по краищата","Затоплете тортилите в сух тиган, напълнете ги и овкусете със сок от лайм"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","сол","няколко капки сок от лайм"]},"nl":{"name":"Fajitawraps met kip","description":"Gekruide kip, paprika en ui in warme tortilla''s","instructions":["Snijd de kip, de paprika en de ui in reepjes en meng de kip met de komijn, het paprikapoeder en zout","Bak de kip 5 minuten in de olie op hoog vuur bruin en gaar","Voeg de paprika en de ui toe en bak 4 minuten tot ze zacht zijn met geblakerde randjes","Verwarm de tortilla''s in een droge pan, vul ze en maak af met limoensap"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","zout","kneepje limoensap"]}}'::jsonb, 169),
  ('l-bean-cheese-quesadilla', 'Bean and Cheese Quesadilla', 'Crisp tortilla filled with kidney beans, corn and melted cheese', 'lunch', 'kidney beans', '🧀', 12, 'quick', 675, 29, 91, 22, 11, 13, 1528, '[{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"cheese","amount":40,"unit":"g"},{"name":"corn","amount":40,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["1/2 tsp ground cumin","pinch of salt"]'::jsonb, '["Roughly mash the drained kidney beans with the cumin and salt, then stir in the corn","Spread the beans over one tortilla, scatter over the grated cheese and top with the second tortilla","Cook in a dry pan over medium heat for 2 to 3 minutes per side until crisp and the cheese has melted","Cut into wedges and serve with the diced tomato"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","tortilla","kidney beans","cheese","corn","tomato","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Кесадия с боб и кашкавал","description":"Хрупкава тортила с червен боб, царевица и разтопен кашкавал","instructions":["Намачкайте на едро отцедения червен боб с кимиона и сол и добавете царевицата","Намажете боба върху едната тортила, поръсете с настъргания кашкавал и сложете отгоре втората тортила","Печете в сух тиган на среден огън по 2–3 минути от всяка страна, докато стане хрупкава и кашкавалът се разтопи","Нарежете на триъгълници и поднесете с нарязания на кубчета домат"],"seasonings":["1/2 ч.л. смлян кимион","щипка сол"]},"nl":{"name":"Quesadilla met bonen en kaas","description":"Knapperige tortilla gevuld met kidneybonen, mais en gesmolten kaas","instructions":["Prak de uitgelekte kidneybonen grof met de komijn en zout en roer de mais erdoor","Smeer de bonen over één tortilla, strooi de geraspte kaas erover en leg de tweede tortilla erop","Bak in een droge pan op middelhoog vuur 2 tot 3 minuten per kant, tot hij knapperig is en de kaas gesmolten is","Snijd in punten en serveer met de tomatenblokjes"],"seasonings":["1/2 tl gemalen komijn","snufje zout"]}}'::jsonb, 170),
  ('l-chicken-burrito-bowl', 'Chicken Burrito Bowl', 'Rice bowl with spiced chicken, beans, corn, tomato and lettuce', 'lunch', 'chicken', '🥗', 20, 'quick', 573, 42, 77, 11, 8, 8, 356, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"lettuce","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Cut the chicken into small pieces, coat with the cumin, paprika and salt and fry in the oil for 6 minutes until cooked through","Warm the drained kidney beans and corn in the same pan for 1 minute","Fill a bowl with the rice, chicken, beans and corn, top with diced tomato and shredded lettuce and squeeze over lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","fresh","quick","chicken","rice","kidney beans","corn","tomato","lettuce","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Бурито купа с пилешко","description":"Купа ориз с пилешко с подправки, боб, царевица, домат и маруля","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Нарежете пилешкото на малки парчета, овкусете го с кимиона, червения пипер и сол и го запържете в олиото за 6 минути, докато се сготви","Затоплете отцедения червен боб и царевицата в същия тиган за 1 минута","Напълнете купа с ориза, пилешкото, боба и царевицата, сложете отгоре нарязания на кубчета домат и нарязаната маруля и изстискайте сок от лайм"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","сол","няколко капки сок от лайм"]},"nl":{"name":"Burritobowl met kip","description":"Rijstkom met gekruide kip, bonen, mais, tomaat en sla","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Snijd de kip in kleine stukjes, wentel ze door de komijn, het paprikapoeder en zout en bak ze 6 minuten in de olie tot ze gaar zijn","Verwarm de uitgelekte kidneybonen en de mais 1 minuut in dezelfde pan","Vul een kom met de rijst, de kip, de bonen en de mais, leg de tomatenblokjes en de gesneden sla erop en knijp er limoensap over"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","zout","kneepje limoensap"]}}'::jsonb, 171),
  ('l-beef-tacos', 'Beef Tacos', 'Spiced beef mince in soft tortillas with lettuce, tomato and cheese', 'lunch', 'beef mince', '🌮', 20, 'quick', 730, 39, 67, 33, 7, 9, 1135, '[{"name":"beef mince","amount":120,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"lettuce","amount":40,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"},{"name":"onion","amount":30,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","salt"]'::jsonb, '["Brown the beef mince with the diced onion in a dry pan over high heat for 6 minutes","Stir in the cumin, paprika, chili flakes, salt and a splash of water and cook for 2 more minutes","Warm the tortillas in a dry pan","Fill them with the beef, shredded lettuce, diced tomato and grated cheese"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","quick","hearty","beef mince","tortilla","lettuce","tomato","cheese","onion","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Такос с телешка кайма","description":"Телешка кайма с подправки в меки тортили с маруля, домат и кашкавал","instructions":["Запържете телешката кайма с нарязания на кубчета лук в сух тиган на силен огън за 6 минути","Добавете кимиона, червения пипер, люспите чили, сол и малко вода и гответе още 2 минути","Затоплете тортилите в сух тиган","Напълнете ги с каймата, нарязаната маруля, нарязания на кубчета домат и настъргания кашкавал"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","1/2 ч.л. люспи чили","сол"]},"nl":{"name":"Taco''s met rundergehakt","description":"Gekruid rundergehakt in zachte tortilla''s met sla, tomaat en kaas","instructions":["Bak het rundergehakt met de blokjes ui 6 minuten bruin in een droge pan op hoog vuur","Roer de komijn, het paprikapoeder, de chilivlokken, zout en een scheutje water erdoor en bak nog 2 minuten","Verwarm de tortilla''s in een droge pan","Vul ze met het gehakt, de gesneden sla, de tomatenblokjes en de geraspte kaas"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","1/2 tl chilivlokken","zout"]}}'::jsonb, 172),
  ('l-sweet-potato-bean-burrito', 'Sweet Potato and Bean Burrito', 'Burrito filled with spiced sweet potato, kidney beans and corn', 'lunch', 'kidney beans', '🍠', 25, 'balanced', 534, 16, 87, 15, 13, 14, 837, '[{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"sweet potato","amount":150,"unit":"g"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"corn","amount":40,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1/2 tsp smoked paprika","salt","squeeze of lime juice"]'::jsonb, '["Peel the sweet potato and cut it into 1 cm cubes","Fry it in the oil over medium heat for 12 minutes, turning now and then, until tender and browned","Add the drained kidney beans, corn, cumin, paprika and salt and cook for 2 minutes, lightly crushing some of the beans","Warm the tortilla, pile the filling down the middle, add lime juice, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","light","tortilla","sweet potato","kidney beans","corn","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Бурито със сладък картоф и боб","description":"Бурито със сладък картоф с подправки, червен боб и царевица","instructions":["Обелете сладкия картоф и го нарежете на кубчета от 1 см","Запържете го в олиото на среден огън за 12 минути, като го обръщате от време на време, докато омекне и се зачерви","Добавете отцедения червен боб, царевицата, кимиона, червения пипер и сол и гответе 2 минути, като леко намачкате част от боба","Затоплете тортилата, наредете плънката по средата, добавете сок от лайм, подгънете краищата и навийте"],"seasonings":["1 ч.л. смлян кимион","1/2 ч.л. пушен червен пипер","сол","няколко капки сок от лайм"]},"nl":{"name":"Burrito met zoete aardappel en bonen","description":"Burrito gevuld met gekruide zoete aardappel, kidneybonen en mais","instructions":["Schil de zoete aardappel en snijd hem in blokjes van 1 cm","Bak hem 12 minuten in de olie op middelhoog vuur gaar en bruin; keer af en toe","Voeg de uitgelekte kidneybonen, de mais, de komijn, het paprikapoeder en zout toe en bak 2 minuten; plet een paar bonen licht","Verwarm de tortilla, leg de vulling in het midden, voeg limoensap toe, vouw de zijkanten naar binnen en rol op"],"seasonings":["1 tl gemalen komijn","1/2 tl gerookt paprikapoeder","zout","kneepje limoensap"]}}'::jsonb, 173),
  ('l-shrimp-avocado-tacos', 'Shrimp and Avocado Tacos', 'Chili-lime shrimp in tortillas with avocado, tomato and lettuce', 'lunch', 'shrimp', '🍤', 15, 'quick', 767, 40, 76, 36, 15, 8, 1055, '[{"name":"shrimp","amount":130,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":80,"unit":"g"},{"name":"lettuce","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","1/2 tsp ground cumin","squeeze of lime juice","salt"]'::jsonb, '["Toss the shrimp with the chili flakes, cumin and salt and fry in the oil over high heat for 2 to 3 minutes until pink","Mash the avocado with lime juice and a pinch of salt","Warm the tortillas in a dry pan and spread them with the avocado","Top with the shrimp, diced tomato and shredded lettuce"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","fresh","quick","hearty","shrimp","tortilla","avocado","tomato","lettuce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Такос със скариди и авокадо","description":"Скариди с чили и лайм в тортили с авокадо, домат и маруля","instructions":["Овкусете скаридите с люспите чили, кимиона и сол и ги запържете в олиото на силен огън за 2–3 минути, докато порозовеят","Намачкайте авокадото със сок от лайм и щипка сол","Затоплете тортилите в сух тиган и ги намажете с авокадото","Сложете отгоре скаридите, нарязания на кубчета домат и нарязаната маруля"],"seasonings":["1/2 ч.л. люспи чили","1/2 ч.л. смлян кимион","няколко капки сок от лайм","сол"]},"nl":{"name":"Taco''s met garnalen en avocado","description":"Garnalen met chili en limoen in tortilla''s met avocado, tomaat en sla","instructions":["Meng de garnalen met de chilivlokken, de komijn en zout en bak ze 2 tot 3 minuten in de olie op hoog vuur tot ze roze zijn","Prak de avocado met limoensap en een snufje zout","Verwarm de tortilla''s in een droge pan en besmeer ze met de avocado","Leg de garnalen, de tomatenblokjes en de gesneden sla erop"],"seasonings":["1/2 tl chilivlokken","1/2 tl gemalen komijn","kneepje limoensap","zout"]}}'::jsonb, 174),
  ('l-chicken-tortilla-soup', 'Chicken Tortilla Soup', 'Tomato broth with chicken, beans and corn, topped with crisp tortilla strips', 'lunch', 'chicken', '🍲', 25, 'balanced', 534, 40, 62, 15, 11, 14, 989, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1/2 tsp chili flakes","1 stock cube","{300} ml water","squeeze of lime juice"]'::jsonb, '["Cut the tortilla into thin strips and toast them in a dry pot over medium heat for 3 minutes until crisp, then set aside","Soften the diced onion in the oil for 3 minutes, then add the cumin and chili flakes","Add the chopped tomatoes, water, stock cube and the chicken in small pieces and simmer for 12 minutes","Stir in the drained kidney beans and corn, heat for 2 minutes, add lime juice and serve topped with the tortilla strips"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","comfort","light","chicken","chopped tomatoes","corn","kidney beans","onion","tortilla","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пилешка супа с тортила","description":"Доматен бульон с пилешко, боб и царевица, с хрупкави ивици тортила отгоре","instructions":["Нарежете тортилата на тънки ивици и ги запечете в суха тенджера на среден огън за 3 минути, докато станат хрупкави, след което ги оставете настрани","Задушете нарязания на кубчета лук в олиото за 3 минути и добавете кимиона и люспите чили","Добавете нарязаните домати, водата, кубчето бульон и пилешкото на малки парчета и варете на тих огън 12 минути","Добавете отцедения червен боб и царевицата, затоплете 2 минути, добавете сок от лайм и поднесете с ивиците тортила отгоре"],"seasonings":["1 ч.л. смлян кимион","1/2 ч.л. люспи чили","1 кубче бульон","{300} мл вода","няколко капки сок от лайм"]},"nl":{"name":"Tortillasoep met kip","description":"Tomatenbouillon met kip, bonen en mais, met knapperige tortillareepjes erop","instructions":["Snijd de tortilla in dunne reepjes en rooster ze 3 minuten in een droge pan op middelhoog vuur knapperig; leg ze apart","Bak de blokjes ui 3 minuten zacht in de olie en voeg dan de komijn en de chilivlokken toe","Voeg de tomatenblokjes, het water, het bouillonblokje en de kip in kleine stukjes toe en laat 12 minuten zachtjes koken","Roer de uitgelekte kidneybonen en de mais erdoor, verwarm 2 minuten, voeg limoensap toe en serveer met de tortillareepjes erop"],"seasonings":["1 tl gemalen komijn","1/2 tl chilivlokken","1 bouillonblokje","{300} ml water","kneepje limoensap"]}}'::jsonb, 175),
  ('l-smoky-bean-chili', 'Smoky Bean Chili', 'Kidney bean and vegetable chili with rice', 'lunch', 'kidney beans', '🌶️', 25, 'balanced', 546, 20, 96, 11, 16, 18, 687, '[{"name":"kidney beans","amount":150,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"rice","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp smoked paprika","1 tsp ground cumin","1/2 tsp chili flakes","salt"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Dice the onion and peppers and soften them in the oil for 5 minutes, then stir in the paprika, cumin and chili flakes","Add the chopped tomatoes and drained kidney beans and simmer for 12 minutes until thick","Stir in the corn, season with salt and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","comfort","light","kidney beans","chopped tomatoes","peppers","onion","corn","rice","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Чили с боб и пушен пипер","description":"Чили от червен боб и зеленчуци с ориз","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Нарежете лука и чушките на кубчета и ги задушете в олиото за 5 минути, след което добавете червения пипер, кимиона и люспите чили","Добавете нарязаните домати и отцедения червен боб и варете на тих огън 12 минути, докато се сгъсти","Добавете царевицата, овкусете със сол и поднесете върху ориза"],"seasonings":["1 ч.л. пушен червен пипер","1 ч.л. смлян кимион","1/2 ч.л. люспи чили","сол"]},"nl":{"name":"Rokerige bonenchili","description":"Chili van kidneybonen en groenten met rijst","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Snijd de ui en de paprika in blokjes en bak ze 5 minuten zacht in de olie; roer dan het paprikapoeder, de komijn en de chilivlokken erdoor","Voeg de tomatenblokjes en de uitgelekte kidneybonen toe en laat 12 minuten zachtjes koken tot de chili dik is","Roer de mais erdoor, breng op smaak met zout en serveer op de rijst"],"seasonings":["1 tl gerookt paprikapoeder","1 tl gemalen komijn","1/2 tl chilivlokken","zout"]}}'::jsonb, 176),
  ('l-huevos-rancheros', 'Huevos Rancheros', 'Fried eggs on tortillas with beans and a spicy tomato sauce', 'lunch', 'eggs', '🍳', 20, 'quick', 726, 31, 84, 29, 11, 12, 1363, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"chopped tomatoes","amount":120,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","1/2 tsp ground cumin","salt"]'::jsonb, '["Soften the diced onion in half the oil for 3 minutes, add the chili flakes and cumin, then the chopped tomatoes, and simmer for 6 minutes","Stir in the drained kidney beans and warm through","Fry the eggs in the remaining oil for 2 to 3 minutes until the whites are set","Warm the tortillas in a dry pan, spoon over the beans and sauce and top each with an egg"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","quick","hearty","eggs","tortilla","kidney beans","chopped tomatoes","onion","oil","stovetop","lunch"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Уевос ранчерос","description":"Яйца на очи върху тортили с боб и пикантен доматен сос","instructions":["Задушете нарязания на кубчета лук в половината олио за 3 минути, добавете люспите чили и кимиона, след това нарязаните домати и варете на тих огън 6 минути","Добавете отцедения червен боб и го затоплете","Изпържете яйцата в останалото олио за 2–3 минути, докато белтъкът стегне","Затоплете тортилите в сух тиган, сложете върху тях боба със соса и по едно яйце отгоре"],"seasonings":["1/2 ч.л. люспи чили","1/2 ч.л. смлян кимион","сол"]},"nl":{"name":"Huevos rancheros","description":"Gebakken eieren op tortilla''s met bonen en een pittige tomatensaus","instructions":["Bak de blokjes ui 3 minuten zacht in de helft van de olie, voeg de chilivlokken en de komijn toe, dan de tomatenblokjes, en laat 6 minuten zachtjes koken","Roer de uitgelekte kidneybonen erdoor en warm ze door","Bak de eieren 2 tot 3 minuten in de rest van de olie, tot het eiwit gestold is","Verwarm de tortilla''s in een droge pan, schep de bonen met saus erop en leg op elke tortilla een ei"],"seasonings":["1/2 tl chilivlokken","1/2 tl gemalen komijn","zout"]}}'::jsonb, 177),
  ('l-turkey-taco-salad', 'Turkey Taco Salad', 'Spiced turkey mince over lettuce with tomato, corn, beans and avocado', 'lunch', 'turkey mince', '🥗', 15, 'quick', 607, 36, 40, 37, 17, 9, 358, '[{"name":"turkey mince","amount":130,"unit":"g"},{"name":"lettuce","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Brown the turkey mince in the oil over high heat for 6 minutes with the cumin, paprika and salt","Shred the lettuce and dice the tomato and avocado","Arrange the lettuce in a bowl and top with the turkey, tomato, corn, drained kidney beans and avocado","Squeeze over lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","fresh","quick","turkey mince","lettuce","tomato","corn","kidney beans","avocado","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Тако салата с пуешка кайма","description":"Пуешка кайма с подправки върху маруля с домат, царевица, боб и авокадо","instructions":["Запържете пуешката кайма в олиото на силен огън за 6 минути с кимиона, червения пипер и сол","Нарежете марулята на ивици, а домата и авокадото на кубчета","Подредете марулята в купа и сложете отгоре каймата, домата, царевицата, отцедения червен боб и авокадото","Изстискайте сок от лайм"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","сол","няколко капки сок от лайм"]},"nl":{"name":"Tacosalade met kalkoen","description":"Gekruid kalkoengehakt op sla met tomaat, mais, bonen en avocado","instructions":["Bak het kalkoengehakt 6 minuten bruin in de olie op hoog vuur met de komijn, het paprikapoeder en zout","Snijd de sla in reepjes en de tomaat en de avocado in blokjes","Leg de sla in een kom en verdeel het gehakt, de tomaat, de mais, de uitgelekte kidneybonen en de avocado erover","Knijp er limoensap over"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","zout","kneepje limoensap"]}}'::jsonb, 178),
  ('l-tofu-fajita-bowl', 'Tofu Fajita Bowl', 'Spiced tofu with peppers, onion and corn over rice', 'lunch', 'tofu', '🫑', 20, 'quick', 590, 33, 71, 22, 9, 9, 133, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"peppers","amount":120,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp smoked paprika","salt","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Cut the tofu into strips, coat with the cumin, paprika and salt and fry in the oil over medium-high heat for 5 minutes","Add the sliced peppers and onion and cook for 5 minutes until soft and lightly charred","Stir in the corn and serve over the rice with lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","tofu","rice","peppers","onion","corn","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Фахита купа с тофу","description":"Тофу с подправки, чушки, лук и царевица върху ориз","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Нарежете тофуто на ивици, овкусете го с кимиона, червения пипер и сол и го запържете в олиото на умерено силен огън за 5 минути","Добавете нарязаните чушки и лук и гответе 5 минути, докато омекнат и леко прегорят","Добавете царевицата и поднесете върху ориза със сок от лайм"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. пушен червен пипер","сол","няколко капки сок от лайм"]},"nl":{"name":"Fajitabowl met tofu","description":"Gekruide tofu met paprika, ui en mais op rijst","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Snijd de tofu in reepjes, wentel ze door de komijn, het paprikapoeder en zout en bak ze 5 minuten in de olie op middelhoog tot hoog vuur","Voeg de reepjes paprika en ui toe en bak 5 minuten tot ze zacht en licht geblakerd zijn","Roer de mais erdoor en serveer op de rijst met limoensap"],"seasonings":["1 tl gemalen komijn","1 tl gerookt paprikapoeder","zout","kneepje limoensap"]}}'::jsonb, 179)
